package com.dailygoals;

import java.util.Arrays;
import java.util.Locale;
import javax.annotation.Nullable;
import lombok.Getter;
import lombok.RequiredArgsConstructor;
import net.runelite.api.gameval.SpriteID;
import net.runelite.client.hiscore.HiscoreSkill;

/**
 * Bosses and other activities a count goal can track. Bosses are matched against the name in
 * the game's "Your X kill count is: N" message, with aliases for messages that word the name
 * differently. The other activities have their own messages; see {@link Kind}.
 * <p>
 * Constant names are stored in saved goals, so don't rename them.
 */
enum Activity
{
	ABYSSAL_SIRE(HiscoreSkill.ABYSSAL_SIRE),
	ALCHEMICAL_HYDRA(HiscoreSkill.ALCHEMICAL_HYDRA),
	AMOXLIATL(HiscoreSkill.AMOXLIATL),
	ARAXXOR(HiscoreSkill.ARAXXOR),
	ARTIO(HiscoreSkill.ARTIO),
	BARROWS_CHESTS(HiscoreSkill.BARROWS_CHESTS, "Barrows chest"),
	BRUTUS(HiscoreSkill.BRUTUS),
	BRYOPHYTA(HiscoreSkill.BRYOPHYTA),
	CALLISTO(HiscoreSkill.CALLISTO),
	CALVARION(HiscoreSkill.CALVARION),
	CERBERUS(HiscoreSkill.CERBERUS),
	CHAMBERS_OF_XERIC(HiscoreSkill.CHAMBERS_OF_XERIC),
	CHAMBERS_OF_XERIC_CHALLENGE_MODE(HiscoreSkill.CHAMBERS_OF_XERIC_CHALLENGE_MODE),
	CHAOS_ELEMENTAL(HiscoreSkill.CHAOS_ELEMENTAL),
	CHAOS_FANATIC(HiscoreSkill.CHAOS_FANATIC),
	COMMANDER_ZILYANA(HiscoreSkill.COMMANDER_ZILYANA),
	CORPOREAL_BEAST(HiscoreSkill.CORPOREAL_BEAST),
	CRAZY_ARCHAEOLOGIST(HiscoreSkill.CRAZY_ARCHAEOLOGIST),
	DAGANNOTH_PRIME(HiscoreSkill.DAGANNOTH_PRIME),
	DAGANNOTH_REX(HiscoreSkill.DAGANNOTH_REX),
	DAGANNOTH_SUPREME(HiscoreSkill.DAGANNOTH_SUPREME),
	DERANGED_ARCHAEOLOGIST(HiscoreSkill.DERANGED_ARCHAEOLOGIST),
	DOOM_OF_MOKHAIOTL(HiscoreSkill.DOOM_OF_MOKHAIOTL),
	DUKE_SUCELLUS(HiscoreSkill.DUKE_SUCELLUS),
	FRACTURED_ARCHIVE(HiscoreSkill.FRACTURED_ARCHIVE),
	GENERAL_GRAARDOR(HiscoreSkill.GENERAL_GRAARDOR),
	GIANT_MOLE(HiscoreSkill.GIANT_MOLE),
	GROTESQUE_GUARDIANS(HiscoreSkill.GROTESQUE_GUARDIANS),
	HESPORI(HiscoreSkill.HESPORI),
	KALPHITE_QUEEN(HiscoreSkill.KALPHITE_QUEEN),
	KING_BLACK_DRAGON(HiscoreSkill.KING_BLACK_DRAGON),
	KRAKEN(HiscoreSkill.KRAKEN),
	KREEARRA(HiscoreSkill.KREEARRA),
	KRIL_TSUTSAROTH(HiscoreSkill.KRIL_TSUTSAROTH),
	LUNAR_CHESTS(HiscoreSkill.LUNAR_CHESTS, "Lunar Chest"),
	MAD_ANGEL(HiscoreSkill.MAD_ANGEL),
	MAGGOT_KING(HiscoreSkill.MAGGOT_KING),
	MIMIC(HiscoreSkill.MIMIC),
	NEX(HiscoreSkill.NEX),
	NIGHTMARE(HiscoreSkill.NIGHTMARE),
	PHOSANIS_NIGHTMARE(HiscoreSkill.PHOSANIS_NIGHTMARE),
	OBOR(HiscoreSkill.OBOR),
	PHANTOM_MUSPAH(HiscoreSkill.PHANTOM_MUSPAH),
	SARACHNIS(HiscoreSkill.SARACHNIS),
	SCORPIA(HiscoreSkill.SCORPIA),
	SCURRIUS(HiscoreSkill.SCURRIUS),
	SHELLBANE_GRYPHON(HiscoreSkill.SHELLBANE_GRYPHON),
	SKOTIZO(HiscoreSkill.SKOTIZO),
	SOL_HEREDIT(HiscoreSkill.SOL_HEREDIT),
	SPINDEL(HiscoreSkill.SPINDEL),
	TEMPOROSS(HiscoreSkill.TEMPOROSS),
	THE_GAUNTLET(HiscoreSkill.THE_GAUNTLET),
	THE_CORRUPTED_GAUNTLET(HiscoreSkill.THE_CORRUPTED_GAUNTLET),
	THE_HUEYCOATL(HiscoreSkill.THE_HUEYCOATL),
	THE_LEVIATHAN(HiscoreSkill.THE_LEVIATHAN),
	THE_ROYAL_TITANS(HiscoreSkill.THE_ROYAL_TITANS, "Royal Titan"),
	THE_WHISPERER(HiscoreSkill.THE_WHISPERER),
	THEATRE_OF_BLOOD(HiscoreSkill.THEATRE_OF_BLOOD),
	THEATRE_OF_BLOOD_HARD_MODE(HiscoreSkill.THEATRE_OF_BLOOD_HARD_MODE),
	THERMONUCLEAR_SMOKE_DEVIL(HiscoreSkill.THERMONUCLEAR_SMOKE_DEVIL),
	TOMBS_OF_AMASCUT(HiscoreSkill.TOMBS_OF_AMASCUT),
	TOMBS_OF_AMASCUT_EXPERT(HiscoreSkill.TOMBS_OF_AMASCUT_EXPERT),
	TZKAL_ZUK(HiscoreSkill.TZKAL_ZUK),
	TZTOK_JAD(HiscoreSkill.TZTOK_JAD),
	VARDORVIS(HiscoreSkill.VARDORVIS),
	VENENATIS(HiscoreSkill.VENENATIS),
	VETION(HiscoreSkill.VETION),
	VORKATH(HiscoreSkill.VORKATH),
	WINTERTODT(HiscoreSkill.WINTERTODT),
	YAMA(HiscoreSkill.YAMA),
	ZALCANO(HiscoreSkill.ZALCANO),
	ZULRAH(HiscoreSkill.ZULRAH),

	CLUES_ALL("Clue scrolls (all)", Kind.CLUE_ANY, HiscoreSkill.CLUE_SCROLL_ALL.getSpriteId(), "Clue scrolls"),
	CLUES_BEGINNER("Clue scrolls (beginner)", Kind.CLUE, HiscoreSkill.CLUE_SCROLL_ALL.getSpriteId(), "Beginner clues"),
	CLUES_EASY("Clue scrolls (easy)", Kind.CLUE, HiscoreSkill.CLUE_SCROLL_ALL.getSpriteId(), "Easy clues"),
	CLUES_MEDIUM("Clue scrolls (medium)", Kind.CLUE, HiscoreSkill.CLUE_SCROLL_ALL.getSpriteId(), "Medium clues"),
	CLUES_HARD("Clue scrolls (hard)", Kind.CLUE, HiscoreSkill.CLUE_SCROLL_ALL.getSpriteId(), "Hard clues"),
	CLUES_ELITE("Clue scrolls (elite)", Kind.CLUE, HiscoreSkill.CLUE_SCROLL_ALL.getSpriteId(), "Elite clues"),
	CLUES_MASTER("Clue scrolls (master)", Kind.CLUE, HiscoreSkill.CLUE_SCROLL_ALL.getSpriteId(), "Master clues"),
	RIFTS_CLOSED("Rifts closed (GotR)", Kind.RIFTS, HiscoreSkill.RIFTS_CLOSED.getSpriteId(), "Rifts closed"),
	SEPULCHRE_FLOORS("Hallowed Sepulchre floors", Kind.SEPULCHRE, HiscoreSkill.AGILITY.getSpriteId(), "Sepulchre floors"),

	OTHER("Other", Kind.KILL, SpriteID.SideIcons.COMBAT, null);

	/**
	 * Which game message counts toward it. See {@link CountMessage} for the patterns.
	 */
	enum Kind
	{
		/** "Your X kill count is: N." */
		KILL,
		/** "You have completed N medium Treasure Trails." for one tier. */
		CLUE,
		/** The same message for any tier; each one counts as one. */
		CLUE_ANY,
		/** "Amount of Rifts you have closed: N." */
		RIFTS,
		/** "You have completed Floor F of the Hallowed Sepulchre! Total completions: N." */
		SEPULCHRE
	}

	/**
	 * The heading the goal picker lists it under.
	 */
	@RequiredArgsConstructor
	enum Category
	{
		BOSS("Bosses"),
		RAID("Raids"),
		MINIGAME("Minigames & activities"),
		CLUE("Clue scrolls"),
		OTHER("Other");

		@Getter
		private final String label;
	}

	@Getter
	private final String name;
	@Getter
	private final Kind kind;
	@Getter
	private final int spriteId;
	/** What a goal on a non-boss activity counts, e.g. "Medium clues"; null for bosses. */
	@Nullable
	private final String countName;
	/** Normalized names a kill count message may use for this boss. */
	private final String[] keys;

	Activity(HiscoreSkill hiscore, String... aliases)
	{
		this.name = hiscore.getName();
		this.kind = Kind.KILL;
		this.spriteId = hiscore.getSpriteId();
		this.countName = null;
		this.keys = new String[aliases.length + 1];
		for (int i = 0; i < aliases.length; i++)
		{
			keys[i] = normalize(aliases[i]);
		}
		keys[aliases.length] = normalize(hiscore.getName());
	}

	Activity(String name, Kind kind, int spriteId, @Nullable String countName)
	{
		this.name = name;
		this.kind = kind;
		this.spriteId = spriteId;
		this.countName = countName;
		this.keys = new String[0];
	}

	/**
	 * Whether the boss name from a kill count message is this boss.
	 */
	boolean matches(String chatName)
	{
		return kind == Kind.KILL && Arrays.asList(keys).contains(normalize(chatName));
	}

	Category getCategory()
	{
		switch (this)
		{
			case CHAMBERS_OF_XERIC:
			case CHAMBERS_OF_XERIC_CHALLENGE_MODE:
			case THEATRE_OF_BLOOD:
			case THEATRE_OF_BLOOD_HARD_MODE:
			case TOMBS_OF_AMASCUT:
			case TOMBS_OF_AMASCUT_EXPERT:
				return Category.RAID;
			case BARROWS_CHESTS:
			case LUNAR_CHESTS:
			case THE_GAUNTLET:
			case THE_CORRUPTED_GAUNTLET:
			case TEMPOROSS:
			case WINTERTODT:
			case ZALCANO:
			case RIFTS_CLOSED:
			case SEPULCHRE_FLOORS:
				return Category.MINIGAME;
			case OTHER:
				return Category.OTHER;
			default:
				return kind == Kind.CLUE || kind == Kind.CLUE_ANY ? Category.CLUE : Category.BOSS;
		}
	}

	/**
	 * The clue tier word in the completion message ("medium"), for single-tier clue goals.
	 */
	@Nullable
	String clueTier()
	{
		return kind == Kind.CLUE && countName != null ? countName.split(" ")[0].toLowerCase(Locale.ROOT) : null;
	}

	/**
	 * What a goal on this counts, e.g. "Zulrah kills" or "Medium clues".
	 */
	String goalName(String customName)
	{
		if (countName != null)
		{
			return countName;
		}
		String boss = this == OTHER ? customName : name;
		return (boss.isEmpty() ? "Boss" : boss) + " kills";
	}

	/**
	 * The goal picker shows the full name; "Other" asks for a name.
	 */
	String pickerName()
	{
		return this == OTHER ? "Other (type a name)" : name;
	}

	@Override
	public String toString()
	{
		return name;
	}

	/**
	 * Lower case, no leading "the", letters and digits only, so "Kree'arra" == "Kree'Arra" and
	 * "Gauntlet" == "The Gauntlet".
	 */
	static String normalize(String name)
	{
		String s = name.toLowerCase(Locale.ROOT).trim();
		if (s.startsWith("the "))
		{
			s = s.substring(4);
		}
		return s.replaceAll("[^a-z0-9]", "");
	}
}

package com.dailygoals;

import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.Value;
import net.runelite.client.util.Text;

/**
 * A count read from a game chat message, such as a boss kill count or a clue completion.
 */
@Value
class CountMessage
{
	// Same as the Chat Commands plugin's kill count pattern
	private static final Pattern KILL_COUNT = Pattern.compile("Your (?<pre>completion count for |subdued |completed )?(?:<col=[0-9a-f]{6}>)?(?<boss>.+?)(?:</col>)? (?<post>(?:(?:kill|harvest|lap|completion|success|Total Ticket) )?(?:count )?)is: ?(?:<col=[0-9a-f]{6}>|@.+?@)(?<kc>[0-9,]+)</col>");
	// Matched with tags removed, as the Loot Tracker plugin does
	private static final Pattern CLUE = Pattern.compile("You have completed ([0-9,]+) (beginner|easy|medium|hard|elite|master) Treasure Trails?\\.");
	// Same as the Chat Commands plugin
	private static final Pattern RIFTS = Pattern.compile("Amount of Rifts you have closed: <col=ff0000>([0-9,]+)</col>\\.", Pattern.CASE_INSENSITIVE);
	private static final Pattern SEPULCHRE = Pattern.compile("You have completed Floor (\\d) of the Hallowed Sepulchre! Total completions: <col=ff0000>([0-9,]+)</col>\\.");

	Activity.Kind kind;
	/** The boss name for kills, the tier ("medium") for clues, otherwise empty. */
	String name;
	long value;
	/** True when {@link #value} is how many to add; false when it's the new running total. */
	boolean increment;

	/**
	 * The counts in a chat message. Usually none; one clue message gives both its tier's total
	 * and one more for "any tier" goals.
	 */
	static List<CountMessage> parse(String message)
	{
		List<CountMessage> counts = new ArrayList<>();

		Matcher matcher = KILL_COUNT.matcher(message);
		// "Your X is: N" without kill/count words is a different message (see Chat Commands)
		if (matcher.find() && !(matcher.group("pre") == null && matcher.group("post").isEmpty()))
		{
			counts.add(new CountMessage(Activity.Kind.KILL, matcher.group("boss"), number(matcher.group("kc")), false));
			return counts;
		}

		matcher = CLUE.matcher(Text.removeTags(message));
		if (matcher.find())
		{
			counts.add(new CountMessage(Activity.Kind.CLUE, matcher.group(2), number(matcher.group(1)), false));
			counts.add(new CountMessage(Activity.Kind.CLUE_ANY, "", 1, true));
			return counts;
		}

		matcher = RIFTS.matcher(message);
		if (matcher.find())
		{
			counts.add(new CountMessage(Activity.Kind.RIFTS, "", number(matcher.group(1)), false));
			return counts;
		}

		matcher = SEPULCHRE.matcher(message);
		if (matcher.find())
		{
			counts.add(new CountMessage(Activity.Kind.SEPULCHRE, "", number(matcher.group(2)), false));
		}
		return counts;
	}

	private static long number(String text)
	{
		return Long.parseLong(text.replace(",", ""));
	}
}

package com.dailygoals;

import java.time.DayOfWeek;
import java.time.ZoneId;
import java.time.ZoneOffset;
import lombok.Getter;
import lombok.RequiredArgsConstructor;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Notification;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

/**
 * The settings page: when goals reset, carry-over, and display options. The goals themselves
 * are edited in the sidebar and stored by {@link GoalStore}.
 */
@ConfigGroup(DailyGoalsConfig.GROUP)
public interface DailyGoalsConfig extends Config
{
	String GROUP = "dailygoals";

	@RequiredArgsConstructor
	enum WeekDay
	{
		MONDAY(DayOfWeek.MONDAY),
		TUESDAY(DayOfWeek.TUESDAY),
		WEDNESDAY(DayOfWeek.WEDNESDAY),
		THURSDAY(DayOfWeek.THURSDAY),
		FRIDAY(DayOfWeek.FRIDAY),
		SATURDAY(DayOfWeek.SATURDAY),
		SUNDAY(DayOfWeek.SUNDAY);

		@Getter
		private final DayOfWeek dayOfWeek;

		@Override
		public String toString()
		{
			String name = name();
			return name.charAt(0) + name.substring(1).toLowerCase();
		}
	}

	@RequiredArgsConstructor
	enum CarryOver
	{
		OFF("Off", false, false),
		EXTRA("Extra progress", true, false),
		MISSED("Missed amount", false, true),
		BOTH("Both", true, true);

		private final String label;
		@Getter
		private final boolean carryExtra;
		@Getter
		private final boolean carryMissed;

		@Override
		public String toString()
		{
			return label;
		}
	}

	@RequiredArgsConstructor
	enum TimeZoneMode
	{
		LOCAL("Local time"),
		UTC("UTC (game reset)");

		private final String label;

		ZoneId zone()
		{
			return this == UTC ? ZoneOffset.UTC : ZoneId.systemDefault();
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	@RequiredArgsConstructor
	enum DisplayLine
	{
		DONE("Done"),
		LEFT("Left"),
		GOAL("Goal"),
		PERCENT("Progress"),
		RATE("XP/h"),
		ETA("Done in"),
		PACE("Pace");

		private final String label;

		/**
		 * Label for a goal's line: per hour reads "Kills/h" and so on for count goals.
		 */
		String label(Goal goal)
		{
			return this == RATE ? goal.rateLabel() : label;
		}

		@Override
		public String toString()
		{
			return this == RATE ? "XP/h (kills/h)" : label;
		}
	}

	@RequiredArgsConstructor
	enum Show
	{
		INFOBOXES("Infoboxes", true, false),
		OVERLAYS("Overlays", false, true),
		BOTH("Both", true, true);

		private final String label;
		@Getter
		private final boolean infoboxes;
		@Getter
		private final boolean overlays;

		@Override
		public String toString()
		{
			return label;
		}
	}

	@RequiredArgsConstructor
	enum HideWhenComplete
	{
		NOTHING("Nothing", false, false),
		OVERLAYS("Overlays", false, true),
		INFOBOXES("Infoboxes", true, false),
		BOTH("Both", true, true);

		private final String label;
		@Getter
		private final boolean infoboxes;
		@Getter
		private final boolean overlays;

		@Override
		public String toString()
		{
			return label;
		}
	}

	@RequiredArgsConstructor
	enum ValueFormat
	{
		AMOUNT("XP / count"),
		PERCENT("Percent");

		private final String label;

		@Override
		public String toString()
		{
			return label;
		}
	}

	@ConfigSection(
		name = "Reset",
		description = "When goals start over and what carries over",
		position = 0
	)
	String resetSection = "reset";

	@ConfigSection(
		name = "Display",
		description = "Overlays, infoboxes, notifications and chat messages",
		position = 1
	)
	String displaySection = "display";

	@ConfigItem(
		keyName = "resetTime",
		section = resetSection,
		name = "Reset time",
		description = "Time of day goals start over, as HH:MM in 24-hour time (e.g. 04:00 or 06:30)",
		position = 0
	)
	default String resetTime()
	{
		return "04:00";
	}

	@ConfigItem(
		keyName = "weeklyResetDay",
		section = resetSection,
		name = "Weekly reset day",
		description = "Day weekly goals start over, at the reset time. (The OSRS weekly reset is Wednesday)",
		position = 1
	)
	default WeekDay weeklyResetDay()
	{
		return WeekDay.MONDAY;
	}

	@ConfigItem(
		keyName = "timeZone",
		section = resetSection,
		name = "Time zone",
		description = "Whether the reset time is your computer's local time or UTC. The OSRS daily reset is 00:00 UTC",
		position = 2
	)
	default TimeZoneMode timeZone()
	{
		return TimeZoneMode.LOCAL;
	}

	@ConfigItem(
		keyName = "carryOver",
		section = resetSection,
		name = "Carry over",
		description = "Extra progress: XP/kills above the goal count toward the next day or week."
			+ " Missed amount: what you didn't finish is added to the next goal."
			+ " Only the last day you played carries over; rest days pass it on",
		position = 3
	)
	default CarryOver carryOver()
	{
		return CarryOver.OFF;
	}

	@Range(min = 10, max = 1000)
	@Units(Units.PERCENT)
	@ConfigItem(
		keyName = "weekendMultiplier",
		section = resetSection,
		name = "Weekend multiplier",
		description = "Daily goals on Saturday and Sunday are this much of the normal amount:"
			+ " 150% makes a 100K goal 150K, 50% halves it. 100% turns it off. Level and weekly goals aren't changed",
		position = 4
	)
	default int weekendMultiplier()
	{
		return 100;
	}

	@ConfigItem(
		keyName = "show",
		name = "Show",
		description = "Show infoboxes, overlays or both, for goals that have them ticked in the sidebar",
		section = displaySection,
		position = 0
	)
	default Show show()
	{
		return Show.BOTH;
	}

	@ConfigItem(
		keyName = "valueFormat",
		name = "Values",
		description = "Show amounts as XP / count or as a percentage of the goal,"
			+ " on infoboxes and the overlay's Done, Left and Pace lines",
		section = displaySection,
		position = 1
	)
	default ValueFormat valueFormat()
	{
		return ValueFormat.AMOUNT;
	}

	@ConfigItem(
		keyName = "hideWhenComplete",
		name = "Hide when complete",
		description = "Hide a goal's overlay, infobox or both once it's reached for the day (or week)."
			+ " Its card in the sidebar stays",
		section = displaySection,
		position = 2
	)
	default HideWhenComplete hideWhenComplete()
	{
		return HideWhenComplete.NOTHING;
	}

	@ConfigItem(
		keyName = "paceColors",
		name = "Pace colours",
		description = "Turn the progress bar amber when you're behind the pace needed to finish by the reset",
		section = displaySection,
		position = 3
	)
	default boolean paceColors()
	{
		return true;
	}

	@ConfigItem(
		keyName = "overlayTopLine",
		name = "Overlay top line",
		description = "What the top line of each goal's overlay shows",
		section = displaySection,
		position = 4
	)
	default DisplayLine overlayTopLine()
	{
		return DisplayLine.DONE;
	}

	@ConfigItem(
		keyName = "overlayBottomLine",
		name = "Overlay bottom line",
		description = "What the bottom line of each goal's overlay shows",
		section = displaySection,
		position = 5
	)
	default DisplayLine overlayBottomLine()
	{
		return DisplayLine.LEFT;
	}

	@ConfigItem(
		keyName = "notifyComplete",
		name = "Notify when done",
		description = "Send a notification when a goal is reached",
		section = displaySection,
		position = 6
	)
	default Notification notifyComplete()
	{
		return Notification.ON;
	}

	@ConfigItem(
		keyName = "notifyMilestones",
		name = "Notify at 50% / 75%",
		description = "Send a notification when a goal is half and three quarters done"
			+ " (a chat message is posted either way when chat messages are on)",
		section = displaySection,
		position = 7
	)
	default Notification notifyMilestones()
	{
		return Notification.OFF;
	}

	@ConfigItem(
		keyName = "chatMessages",
		name = "Chat messages",
		description = "Post a chat message at 50% / 75%, when a goal is reached and when goals reset",
		section = displaySection,
		position = 8
	)
	default boolean chatMessages()
	{
		return true;
	}
}

package com.dailygoals;

import java.awt.Color;
import java.awt.image.BufferedImage;
import lombok.Getter;
import lombok.Setter;
import net.runelite.client.ui.overlay.infobox.InfoBox;

/**
 * Shows the XP or count left for one goal (or the percent done), or how far past it you are ("+10K").
 */
class DailyGoalsInfoBox extends InfoBox
{
	private final DailyGoalsPlugin plugin;
	private final DailyGoalsConfig config;
	private final String goalId;

	/** {@link Goal#targetKey()} the image was made for, so a changed goal gets a new icon. */
	@Getter
	@Setter
	private String iconTarget;

	DailyGoalsInfoBox(BufferedImage image, DailyGoalsPlugin plugin, DailyGoalsConfig config, String goalId, String iconTarget)
	{
		super(image, plugin);
		this.plugin = plugin;
		this.config = config;
		this.goalId = goalId;
		this.iconTarget = iconTarget;
	}

	@Override
	public String getText()
	{
		GoalStatus status = plugin.status(goalId);
		if (status == null)
		{
			return null;
		}
		// The Values setting: XP / count left, or percent done
		boolean percent = config.valueFormat() == DailyGoalsConfig.ValueFormat.PERCENT;
		if (status.getOver() > 0)
		{
			return "+" + (percent ? Formats.shortPercent(status.getOver(), status.getTarget()) : Formats.shortNumber(status.getOver()));
		}
		if (status.isComplete())
		{
			return "Done";
		}
		return percent ? Formats.shortPercent(status.getDone(), status.getTarget()) : Formats.shortNumber(status.getLeft());
	}

	@Override
	public Color getTextColor()
	{
		GoalStatus status = plugin.status(goalId);
		return status != null && status.isComplete() ? Color.GREEN : Color.WHITE;
	}

	@Override
	public String getTooltip()
	{
		GoalStatus status = plugin.status(goalId);
		if (status == null)
		{
			return null;
		}

		Goal goal = status.getGoal();
		StringBuilder tooltip = new StringBuilder(goal.isWeekly() ? "Weekly goal: " : "Daily goal: ").append(goal.name())
			.append("</br>Done: ").append(Formats.number(status.getDone()))
			.append(" / ").append(Formats.number(status.getTarget()));
		if (status.getOver() > 0)
		{
			tooltip.append("</br>Over by: ").append(Formats.number(status.getOver()));
		}
		else
		{
			tooltip.append("</br>Left: ").append(Formats.number(status.getLeft()))
				.append("</br>Done in: ").append(Formats.duration(status.getEtaMillis()))
				.append("</br>Pace: ").append(Formats.pace(status.getPace()));
		}
		tooltip.append("</br>").append(goal.rateLabel()).append(": ").append(Formats.number(status.getRate()));
		if (status.getStreak() > 0)
		{
			tooltip.append("</br>Streak: ").append(status.getStreak());
		}

		GoalProgress progress = status.getProgress();
		if (progress.extra > 0)
		{
			tooltip.append("</br>Carried over: ").append(Formats.number(progress.extra));
		}
		if (progress.missed > 0)
		{
			tooltip.append("</br>Missed last time: ").append(Formats.number(progress.missed));
		}
		return tooltip.toString();
	}

	@Override
	public boolean render()
	{
		GoalStatus status = plugin.status(goalId);
		return status != null && status.isActive()
			&& !(config.hideWhenComplete().isInfoboxes() && status.isComplete());
	}

	@Override
	public String getName()
	{
		return super.getName() + goalId;
	}
}

package com.dailygoals;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.components.ComponentOrientation;
import net.runelite.client.ui.overlay.components.ImageComponent;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.PanelComponent;
import net.runelite.client.ui.overlay.components.ProgressBarComponent;
import net.runelite.client.ui.overlay.components.SplitComponent;
import static net.runelite.api.MenuAction.RUNELITE_OVERLAY;
import static net.runelite.api.MenuAction.RUNELITE_OVERLAY_CONFIG;
import static net.runelite.client.ui.overlay.OverlayManager.OPTION_CONFIGURE;

/**
 * One goal's on-screen box, laid out like the XP Tracker's: icon and two lines of text, with a
 * progress bar below.
 */
class DailyGoalsOverlay extends OverlayPanel
{
	// Same sizes as the XP Tracker's box
	private static final int BORDER_SIZE = 2;
	private static final int TEXT_AND_PROGRESS_BAR_GAP = 2;
	private static final int TEXT_AND_ICON_GAP = 4;
	private static final Rectangle TEXT_AND_ICON_COMPONENT_BORDER = new Rectangle(2, 1, 4, 0);
	private static final Color BAR_BACKGROUND = new Color(61, 56, 49);
	private static final Color GOOD = new Color(80, 220, 80);

	private final PanelComponent iconTextSplitPanel = new PanelComponent();
	private final DailyGoalsPlugin plugin;
	private final DailyGoalsConfig config;
	private final String goalId;

	DailyGoalsOverlay(DailyGoalsPlugin plugin, DailyGoalsConfig config, String goalId)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		this.goalId = goalId;
		panelComponent.setBorder(new Rectangle(BORDER_SIZE, BORDER_SIZE, BORDER_SIZE, BORDER_SIZE));
		panelComponent.setGap(new Point(0, TEXT_AND_PROGRESS_BAR_GAP));
		iconTextSplitPanel.setBorder(TEXT_AND_ICON_COMPONENT_BORDER);
		iconTextSplitPanel.setBackgroundColor(null);
		addMenuEntry(RUNELITE_OVERLAY_CONFIG, OPTION_CONFIGURE, "Daily Goals overlay");
		addMenuEntry(RUNELITE_OVERLAY, "Reset today", "Daily goal", e -> plugin.restartPeriod(goalId));
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		GoalStatus status = plugin.status(goalId);
		BufferedImage icon = status == null ? null : plugin.getIcon(status.getGoal());
		if (status == null || icon == null || !status.isActive() || (config.hideWhenComplete().isOverlays() && status.isComplete()))
		{
			return null;
		}

		iconTextSplitPanel.getChildren().clear();

		// RS small font, so the overlay isn't huge
		graphics.setFont(FontManager.getRunescapeSmallFont());

		final SplitComponent textSplit = SplitComponent.builder()
			.first(line(config.overlayTopLine(), status))
			.second(line(config.overlayBottomLine(), status))
			.orientation(ComponentOrientation.VERTICAL)
			.build();

		final SplitComponent iconTextSplit = SplitComponent.builder()
			.first(new ImageComponent(icon))
			.second(textSplit)
			.orientation(ComponentOrientation.HORIZONTAL)
			.gap(new Point(TEXT_AND_ICON_GAP, 0))
			.build();

		iconTextSplitPanel.getChildren().add(iconTextSplit);

		final ProgressBarComponent progressBar = new ProgressBarComponent();
		progressBar.setBackgroundColor(BAR_BACKGROUND);
		progressBar.setForegroundColor(plugin.barColor(status));
		progressBar.setLeftLabel("0");
		progressBar.setRightLabel(Formats.shortNumber(status.getTarget()));
		progressBar.setValue(Math.min(100, status.percent()));

		panelComponent.getChildren().add(iconTextSplitPanel);
		panelComponent.getChildren().add(progressBar);

		return super.render(graphics);
	}

	@Override
	public String getName()
	{
		// Each goal's box keeps its own saved position
		return super.getName() + goalId;
	}

	private LineComponent line(DailyGoalsConfig.DisplayLine line, GoalStatus status)
	{
		// The Values setting: Done, Left and Pace as XP / count, or as a percentage of the goal
		boolean percent = config.valueFormat() == DailyGoalsConfig.ValueFormat.PERCENT;
		long target = status.getTarget();

		String value;
		Color color = Color.WHITE;
		switch (line)
		{
			case DONE:
				value = percent ? Formats.percent(status.getDone(), target) : Formats.number(status.getDone());
				break;
			case LEFT:
				if (status.getOver() > 0)
				{
					value = "+" + (percent ? Formats.percent(status.getOver(), target) : Formats.number(status.getOver()));
					color = GOOD;
				}
				else
				{
					value = percent ? Formats.percent(status.getLeft(), target) : Formats.number(status.getLeft());
				}
				break;
			case GOAL:
				value = Formats.number(status.getTarget());
				break;
			case RATE:
				value = Formats.number(status.getRate());
				break;
			case ETA:
				value = status.isComplete() ? "Done" : Formats.duration(status.getEtaMillis());
				break;
			case PACE:
				value = status.isComplete() ? "Done"
					: percent ? Formats.pacePercent(status.getPace(), target) : Formats.pace(status.getPace());
				color = status.isComplete() || status.getPace() >= 0 ? GOOD : DailyGoalsPlugin.BEHIND_PACE_COLOR;
				break;
			case PERCENT:
			default:
				// Past the goal it shows how far over, e.g. "+10.0%"
				double progress = status.percent();
				if (progress > 100)
				{
					value = String.format("+%.1f%%", progress - 100);
					color = GOOD;
				}
				else
				{
					value = String.format("%.1f%%", progress);
				}
				break;
		}

		return LineComponent.builder()
			.left(line.label(status.getGoal()) + ":")
			.right(value)
			.rightColor(color)
			.build();
	}
}

package com.dailygoals;

import java.awt.BorderLayout;
import java.awt.Color;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.stream.Collectors;
import javax.annotation.Nullable;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JMenu;
import javax.swing.JMenuItem;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.DynamicGridLayout;
import net.runelite.client.ui.PluginPanel;

/**
 * The sidebar: a header with "Add goal", the logged-in character with a menu to copy goals from
 * other characters, the goal editor when it's open, and a {@link GoalCard} per goal. Reset,
 * carry-over and display options are on the settings page.
 */
class DailyGoalsPanel extends PluginPanel
{
	private final DailyGoalsPlugin plugin;
	private final GoalEditor editor;
	private final JButton addButton = PanelStyle.smallButton("Add goal");
	/** Shows whose goals these are; opens the copy-from-another-character menu. */
	private final JButton characterButton = PanelStyle.smallButton("");
	/** Holds the editor while it's open; empty otherwise. */
	private final JPanel editorSlot = new JPanel(new DynamicGridLayout(0, 1, 0, 0));
	private final JPanel goalList = new JPanel(new DynamicGridLayout(0, 1, 0, 8));
	private final JLabel noGoalsLabel = PanelStyle.smallLabel("<html>No goals for this character yet. Click <b>Add goal</b>,"
		+ " or copy goals from another character with the menu above.</html>");
	private final JLabel loggedOutLabel = PanelStyle.smallLabel("<html>Log in to see this character's goals.</html>");

	private final List<GoalCard> cards = new ArrayList<>();
	/** The goals the cards were built for, to tell when they need rebuilding. */
	private List<Goal> cardGoals;
	private List<String> cardIds = new ArrayList<>();
	private List<GoalView> shownViews = new ArrayList<>();
	/** The logged-in character's name; null while logged out. */
	@Nullable
	private String character;

	DailyGoalsPanel(DailyGoalsPlugin plugin, SkillIconManager skillIconManager, SpriteManager spriteManager)
	{
		this.plugin = plugin;
		this.editor = new GoalEditor(skillIconManager, spriteManager, this::onEditorSave, this::closeEditor);

		setBorder(new EmptyBorder(10, 10, 10, 10));
		setLayout(new DynamicGridLayout(0, 1, 0, 10));

		addButton.addActionListener(e -> openEditor(null));
		JPanel header = new JPanel(new BorderLayout());
		header.setOpaque(false);
		header.add(PanelStyle.heading("Daily Goals", Color.WHITE), BorderLayout.WEST);
		header.add(addButton, BorderLayout.EAST);

		characterButton.setHorizontalAlignment(SwingConstants.LEFT);
		characterButton.addActionListener(e -> showCharacterMenu());

		editorSlot.setOpaque(false);
		goalList.setOpaque(false);

		add(header);
		add(characterButton);
		add(editorSlot);
		add(goalList);
		add(PanelStyle.smallLabel("<html>Reset time, weekly reset day, carry over and overlay options are in the plugin's settings.</html>"));

		setCharacter(null);
	}

	/**
	 * The character whose goals are shown, or null when logged out.
	 */
	void setCharacter(@Nullable String name)
	{
		character = name;
		characterButton.setText(name == null ? "Not logged in" : name + "  ▾");
		characterButton.setToolTipText(name == null ? null : "These goals belong to " + name + ". Click to copy goals from your other characters");
		characterButton.setEnabled(name != null);
		addButton.setEnabled(name != null);
		if (name == null)
		{
			closeEditor();
		}

		// Rebuild so the empty-list message matches
		cardGoals = null;
		showGoals(shownViews);
	}

	/**
	 * Show the goals and their progress. Cards are rebuilt only when the goals themselves change;
	 * otherwise they're just updated.
	 */
	void showGoals(List<GoalView> views)
	{
		shownViews = views;
		List<Goal> goals = views.stream().map(GoalView::getGoal).collect(Collectors.toList());
		if (!goals.equals(cardGoals))
		{
			cardGoals = goals;
			rebuildCards(goals);
		}

		for (int i = 0; i < cards.size(); i++)
		{
			cards.get(i).update(views.get(i));
		}
		goalList.revalidate();
		goalList.repaint();
	}

	private void rebuildCards(List<Goal> goals)
	{
		cards.clear();
		cardIds = goals.stream().map(Goal::getId).collect(Collectors.toList());
		goalList.removeAll();
		if (goals.isEmpty())
		{
			goalList.add(character == null ? loggedOutLabel : noGoalsLabel);
		}

		for (int i = 0; i < goals.size(); i++)
		{
			GoalCard card = new GoalCard(plugin, goals.get(i), i, goals.size(), this::onEditClicked);
			card.setEditing(editor.isEditing(goals.get(i).getId()));
			cards.add(card);
			goalList.add(card);
		}
	}

	/**
	 * A menu with each other character that has goals; each lists its goals with "+" to copy one
	 * to this character, plus "Add all".
	 */
	private void showCharacterMenu()
	{
		JPopupMenu menu = new JPopupMenu();
		List<GoalStore.CharacterGoals> others = plugin.otherCharacters();
		if (others.isEmpty())
		{
			JMenuItem none = new JMenuItem("No other characters have goals yet");
			none.setEnabled(false);
			menu.add(none);
		}

		for (GoalStore.CharacterGoals other : others)
		{
			JMenu submenu = new JMenu(other.getName());
			JMenuItem all = new JMenuItem("+  Add all (" + other.getGoals().size() + ")");
			all.setToolTipText("Copy all of " + other.getName() + "'s goals to " + character);
			all.addActionListener(e -> plugin.addGoals(other.getGoals()));
			submenu.add(all);
			submenu.addSeparator();

			for (Goal goal : other.getGoals())
			{
				JMenuItem item = new JMenuItem("+  " + goal.name() + summary(goal));
				item.setToolTipText("Copy this goal to " + character);
				item.addActionListener(e -> plugin.addGoals(Collections.singletonList(goal)));
				submenu.add(item);
			}
			menu.add(submenu);
		}

		menu.show(characterButton, 0, characterButton.getHeight());
	}

	/**
	 * " (100K a day)"; nothing for level goals, whose name says it all.
	 */
	private static String summary(Goal goal)
	{
		if (goal.isLevel())
		{
			return "";
		}
		return " (" + Formats.shortNumber(goal.getAmount()) + (goal.isWeekly() ? " a week)" : " a day)");
	}

	/**
	 * Edit opens the editor; clicking it again on the same goal saves and closes it.
	 */
	private void onEditClicked(Goal goal)
	{
		if (editor.isEditing(goal.getId()))
		{
			editor.save();
		}
		else
		{
			openEditor(goal);
		}
	}

	private void openEditor(@Nullable Goal goal)
	{
		editor.open(goal);
		editorSlot.removeAll();
		editorSlot.add(editor);
		updateEditButtons();
		revalidate();
		repaint();
		SwingUtilities.invokeLater(() -> getScrollPane().getVerticalScrollBar().setValue(0));
	}

	private void closeEditor()
	{
		editor.close();
		editorSlot.removeAll();
		updateEditButtons();
		revalidate();
		repaint();
	}

	private void onEditorSave(Goal goal)
	{
		plugin.saveGoal(goal);
		closeEditor();
	}

	private void updateEditButtons()
	{
		for (int i = 0; i < cards.size(); i++)
		{
			cards.get(i).setEditing(editor.isEditing(cardIds.get(i)));
		}
	}
}

package com.dailygoals;

import com.google.inject.Provides;
import java.awt.Color;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.UUID;
import java.util.stream.Collectors;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.Notifier;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.ProfileChanged;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.SkillColor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.infobox.InfoBoxManager;
import net.runelite.client.util.ImageUtil;

/**
 * Daily and weekly goals: XP, levels, boss kills and other counts.
 * <p>
 * Threading: progress, overlays and infoboxes are only touched on the client thread. The
 * sidebar runs on the Swing thread; it changes goals through {@link #saveGoal} and friends,
 * which write config, and gets {@link GoalView} snapshots back from {@link #updatePanel}.
 */
@Slf4j
@PluginDescriptor(
	name = "Daily Goals",
	description = "Daily and weekly XP, level, boss and activity goals with streaks",
	tags = {"xp", "kc", "goal", "daily", "weekly", "boss", "kill", "count", "tracker", "infobox", "streak", "clue"}
)
public class DailyGoalsPlugin extends Plugin
{
	static final Color BEHIND_PACE_COLOR = new Color(230, 160, 40);
	private static final Color COUNT_BAR_COLOR = new Color(161, 40, 40);
	private static final Color OVERALL_BAR_COLOR = new Color(82, 161, 82);
	private static final int[] MILESTONES = {50, 75};
	// Skill XP isn't loaded the moment LOGGED_IN fires; the XP Tracker waits two ticks too
	private static final int LOGIN_SETTLE_TICKS = 2;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private DailyGoalsConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private GoalStore store;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private InfoBoxManager infoBoxManager;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private SkillIconManager skillIconManager;

	@Inject
	private SpriteManager spriteManager;

	@Inject
	private Notifier notifier;

	@Inject
	private ChatMessageManager chatMessageManager;

	private DailyGoalsPanel panel;
	private NavigationButton navButton;

	/** The logged-in character's goals, in panel order. Replaced as a whole, so the Swing thread can read it. */
	private volatile List<Goal> goals = Collections.emptyList();
	/** The character (RuneScape profile) {@link #goals} belong to; null while logged out. */
	@Nullable
	private volatile String goalsProfile;

	/** Progress per goal id for the logged-in account; null while logged out. */
	@Nullable
	private Map<String, GoalProgress> progress;
	private String progressProfile;

	/** Per-hour rates for this login, per goal id. */
	private final Map<String, RateTracker> rates = new HashMap<>();
	/** Icons by {@link Goal#targetKey()}. */
	private final Map<String, BufferedImage> icons = new HashMap<>();
	private final Set<String> iconsRequested = new HashSet<>();
	private final Map<String, DailyGoalsOverlay> overlays = new HashMap<>();
	private final Map<String, DailyGoalsInfoBox> infoBoxes = new HashMap<>();
	private List<GoalView> shownViews;
	private int loginTicks;

	@Provides
	DailyGoalsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(DailyGoalsConfig.class);
	}

	@Override
	protected void startUp()
	{
		panel = new DailyGoalsPanel(this, skillIconManager, spriteManager);
		navButton = NavigationButton.builder()
			.tooltip("Daily Goals")
			.icon(ImageUtil.loadImageResource(getClass(), "icon.png"))
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		loginTicks = 0;
		clientThread.invokeLater(() ->
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				loginTicks = LOGIN_SETTLE_TICKS;
			}
			update();
		});
	}

	@Override
	protected void shutDown()
	{
		clientToolbar.removeNavigation(navButton);
		clientThread.invokeLater(() ->
		{
			saveProgress();
			clearCharacter();
			overlays.values().forEach(overlayManager::remove);
			overlays.clear();
			infoBoxes.values().forEach(infoBoxManager::removeInfoBox);
			infoBoxes.clear();
			icons.clear();
			iconsRequested.clear();
			shownViews = null;
		});
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		switch (event.getGameState())
		{
			case LOGIN_SCREEN:
				saveProgress();
				clearCharacter();
				update();
				// fall through
			case LOGGING_IN:
			case HOPPING:
			case CONNECTION_LOST:
				loginTicks = 0;
				break;
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		// Goals and progress are saved as they change; the next update loads the new character's
		clearCharacter();
	}

	@Subscribe
	public void onProfileChanged(ProfileChanged event)
	{
		// A different RuneLite profile has different saved goals
		clientThread.invokeLater(() ->
		{
			clearCharacter();
			update();
		});
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (loginTicks < LOGIN_SETTLE_TICKS)
		{
			loginTicks++;
			return;
		}
		update();
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		// The same message types the Chat Commands plugin reads kill counts from
		if (event.getType() != ChatMessageType.GAMEMESSAGE
			&& event.getType() != ChatMessageType.SPAM
			&& event.getType() != ChatMessageType.TRADE
			&& event.getType() != ChatMessageType.FRIENDSCHATNOTIFICATION)
		{
			return;
		}

		List<CountMessage> counts = CountMessage.parse(event.getMessage());
		if (counts.isEmpty())
		{
			return;
		}

		update();
		if (progress == null)
		{
			return;
		}

		GoalSchedule schedule = GoalSchedule.of(config);
		for (CountMessage count : counts)
		{
			for (Goal goal : goals)
			{
				GoalProgress goalProgress = progress.get(goal.getId());
				if (goalProgress == null || !goal.counts(count))
				{
					continue;
				}

				if (count.isIncrement())
				{
					goalProgress.add(count.getValue());
				}
				else
				{
					goalProgress.observeTotal(count.getValue());
				}
				announce(goal, goalProgress, schedule);
			}
		}
		saveProgress();
		updatePanel();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		// Progress is written by this plugin as it goes; that needs no reaction
		if (!DailyGoalsConfig.GROUP.equals(event.getGroup()) || GoalStore.PROGRESS_KEY.equals(event.getKey()))
		{
			return;
		}

		clientThread.invokeLater(() ->
		{
			switch (event.getKey())
			{
				case GoalStore.GOALS_KEY:
					String profile = goalsProfile;
					if (profile != null)
					{
						goals = Collections.unmodifiableList(store.loadGoals(profile));
					}
					break;
				case "resetTime":
				case "timeZone":
				case "weeklyResetDay":
					// Moving the reset shouldn't wipe the period in progress: re-date it instead
					moveProgressToCurrentPeriods();
					break;
			}
			update();
		});
	}

	// Called from the panel (Swing thread)

	/**
	 * Add a goal, or replace the one with the same id.
	 */
	void saveGoal(Goal goal)
	{
		if (goal.getId() == null)
		{
			goal.setId(UUID.randomUUID().toString());
		}

		List<Goal> list = new ArrayList<>(goals);
		boolean replaced = false;
		for (int i = 0; i < list.size(); i++)
		{
			if (list.get(i).getId().equals(goal.getId()))
			{
				list.set(i, goal);
				replaced = true;
			}
		}
		if (!replaced)
		{
			list.add(goal);
		}
		writeGoals(list);
	}

	void setGoalEnabled(String id, boolean enabled)
	{
		Goal goal = getGoal(id);
		if (goal != null && goal.isEnabled() != enabled)
		{
			Goal changed = goal.copy();
			changed.setEnabled(enabled);
			saveGoal(changed);
		}
	}

	void removeGoal(String id)
	{
		writeGoals(goals.stream().filter(g -> !g.getId().equals(id)).collect(Collectors.toList()));
	}

	/**
	 * Move a goal up (-1) or down (+1) in the list.
	 */
	void moveGoal(String id, int direction)
	{
		List<Goal> list = new ArrayList<>(goals);
		for (int i = 0; i < list.size(); i++)
		{
			int j = i + direction;
			if (list.get(i).getId().equals(id) && j >= 0 && j < list.size())
			{
				Collections.swap(list, i, j);
				writeGoals(list);
				return;
			}
		}
	}

	/**
	 * Copy goals (from another character) to this character's list, as new goals.
	 */
	void addGoals(List<Goal> copies)
	{
		List<Goal> list = new ArrayList<>(goals);
		for (Goal source : copies)
		{
			Goal goal = source.copy();
			goal.setId(UUID.randomUUID().toString());
			list.add(goal);
		}
		writeGoals(list);
	}

	/**
	 * Every other character that has goals, for the panel's copy menu.
	 */
	List<GoalStore.CharacterGoals> otherCharacters()
	{
		String profile = goalsProfile;
		return profile == null ? Collections.emptyList() : store.otherCharacters(profile);
	}

	/**
	 * Start a goal's count for this period over from now. Also used by the overlay's menu.
	 */
	void restartPeriod(String goalId)
	{
		clientThread.invokeLater(() ->
		{
			GoalProgress goalProgress = getProgress(goalId);
			if (goalProgress != null)
			{
				goalProgress.restartPeriod();
				rates.remove(goalId);
				update();
			}
		});
	}

	// Used by the overlay and infobox (client thread)

	@Nullable
	Goal getGoal(String id)
	{
		for (Goal goal : goals)
		{
			if (goal.getId().equals(id))
			{
				return goal;
			}
		}
		return null;
	}

	/**
	 * A goal's numbers right now, or null when there's nothing to show (logged out).
	 */
	@Nullable
	GoalStatus status(String goalId)
	{
		Goal goal = getGoal(goalId);
		GoalProgress goalProgress = getProgress(goalId);
		return goal == null || goalProgress == null ? null : status(goal, goalProgress, GoalSchedule.of(config));
	}

	@Nullable
	BufferedImage getIcon(Goal goal)
	{
		String key = goal.targetKey();
		return key == null ? null : icons.get(key);
	}

	/**
	 * Bar colour for a goal: the skill's colour (red for counts), amber when behind pace.
	 */
	Color barColor(GoalStatus status)
	{
		return config.paceColors() && status.isBehind() ? BEHIND_PACE_COLOR : baseColor(status.getGoal());
	}

	// Tracking

	/**
	 * Load the character's goals and progress if needed, start a new period for goals whose
	 * reset has passed, record XP, then bring the overlays, infoboxes and panel up to date.
	 */
	private void update()
	{
		String profile = configManager.getRSProfileKey();
		boolean loggedIn = profile != null && client.getGameState() == GameState.LOGGED_IN;
		if (loggedIn && !profile.equals(goalsProfile))
		{
			loadCharacter(profile);
		}
		boolean tracking = loggedIn && loginTicks >= LOGIN_SETTLE_TICKS;

		if (tracking)
		{
			if (progress == null || !profile.equals(progressProfile))
			{
				progress = store.loadProgress(profile);
				progressProfile = profile;
			}
			track(GoalSchedule.of(config), System.currentTimeMillis());
			saveProgress();
		}

		for (Goal goal : goals)
		{
			requestIcon(goal);
		}
		syncOverlays();
		syncInfoBoxes();
		updatePanel();
	}

	private void track(GoalSchedule schedule, long now)
	{
		List<String> resets = new ArrayList<>();
		Set<String> ids = new HashSet<>();
		for (Goal goal : goals)
		{
			String target = goal.targetKey();
			if (target == null)
			{
				continue;
			}
			ids.add(goal.getId());

			long periodStart = schedule.periodStart(goal, now);
			GoalProgress goalProgress = progress.get(goal.getId());
			if (goalProgress == null || !target.equals(goalProgress.target))
			{
				// New goal, or it now counts something else
				goalProgress = new GoalProgress(target, periodStart);
				progress.put(goal.getId(), goalProgress);
				rates.remove(goal.getId());
			}
			else if (goalProgress.day < periodStart)
			{
				String carried = rollover(goal, goalProgress, schedule, periodStart);
				if (goal.isEnabled() && carried != null)
				{
					resets.add(carried);
				}
				rates.remove(goal.getId());
			}

			if (goal.isXp())
			{
				goalProgress.observeXp(goal.isOverall() ? client.getOverallExperience() : client.getSkillExperience(goal.getSkill()));
			}
			rates.computeIfAbsent(goal.getId(), id -> new RateTracker(goal.isXp())).observe(goalProgress.gained, now);
			announce(goal, goalProgress, schedule);
		}
		progress.keySet().retainAll(ids);
		rates.keySet().retainAll(ids);

		if (!resets.isEmpty())
		{
			chat("Goals reset." + String.join("", resets));
		}
	}

	/**
	 * Start a new period for a goal.
	 *
	 * @return carry-over details for the reset chat message, "" for none, or null when the
	 * period that ended didn't count
	 */
	@Nullable
	private String rollover(Goal goal, GoalProgress goalProgress, GoalSchedule schedule, long periodStart)
	{
		boolean endedActive = schedule.isActive(goal, goalProgress.day);
		boolean skipped = schedule.missedBetween(goal, goalProgress.day, periodStart);
		long amount = status(goal, goalProgress, schedule).getAmount();
		// Carry-over toward a level makes no sense: the XP still needed is worked out fresh
		DailyGoalsConfig.CarryOver carryOver = goal.isLevel() ? DailyGoalsConfig.CarryOver.OFF : config.carryOver();
		goalProgress.rollover(periodStart, amount, carryOver, endedActive, skipped);
		log.debug("New period for {}: extra {}, missed {}, streak {}", goal.name(), goalProgress.extra, goalProgress.missed, goalProgress.streak);

		if (!endedActive)
		{
			return null;
		}
		if (goalProgress.extra > 0)
		{
			return " " + goal.name() + ": " + Formats.number(goalProgress.extra) + " carried over.";
		}
		if (goalProgress.missed > 0)
		{
			return " " + goal.name() + ": " + Formats.number(goalProgress.missed) + " missed, added to the next goal.";
		}
		return "";
	}

	/**
	 * Announce milestones and completion, once each per period.
	 */
	private void announce(Goal goal, GoalProgress goalProgress, GoalSchedule schedule)
	{
		GoalStatus status = status(goal, goalProgress, schedule);
		boolean quiet = !goal.isEnabled() || !status.isActive();

		if (status.isComplete())
		{
			if (!goalProgress.completed)
			{
				goalProgress.completed = true;
				goalProgress.milestone = 100;
				if (!quiet)
				{
					String streak = status.getStreak() > 1 ? " Streak: " + status.getStreak() + "." : "";
					String message = "Goal complete: " + goal.name() + " (" + Formats.number(status.getDone()) + ")!" + streak;
					notifier.notify(config.notifyComplete(), message);
					chat(message);
				}
			}
			return;
		}

		// The goal was raised after it was reached
		goalProgress.completed = false;

		for (int milestone : MILESTONES)
		{
			if (status.percent() >= milestone && goalProgress.milestone < milestone)
			{
				goalProgress.milestone = milestone;
				if (!quiet)
				{
					String message = goal.name() + ": " + milestone + "% of the goal ("
						+ Formats.number(status.getDone()) + " / " + Formats.number(status.getTarget()) + ")";
					notifier.notify(config.notifyMilestones(), message);
					chat(message);
				}
			}
		}
	}

	private GoalStatus status(Goal goal, GoalProgress goalProgress, GoalSchedule schedule)
	{
		RateTracker rate = rates.get(goal.getId());
		long now = System.currentTimeMillis();
		return GoalStatus.of(goal, goalProgress, schedule, config.weekendMultiplier(), rate == null ? 0 : rate.perHour(now), now);
	}

	private void moveProgressToCurrentPeriods()
	{
		if (progress == null)
		{
			return;
		}

		GoalSchedule schedule = GoalSchedule.of(config);
		long now = System.currentTimeMillis();
		for (Goal goal : goals)
		{
			GoalProgress goalProgress = progress.get(goal.getId());
			if (goalProgress != null)
			{
				goalProgress.day = schedule.periodStart(goal, now);
			}
		}
		saveProgress();
	}

	@Nullable
	private GoalProgress getProgress(String goalId)
	{
		return progress == null ? null : progress.get(goalId);
	}

	private void saveProgress()
	{
		if (progress != null && progressProfile != null)
		{
			store.saveProgress(progressProfile, progress);
		}
	}

	/**
	 * A character logged in: load its goals (taking over the old shared list if it's the first).
	 */
	private void loadCharacter(String profile)
	{
		store.migrateSharedGoals(profile);
		goals = Collections.unmodifiableList(store.loadGoals(profile));
		goalsProfile = profile;
		String name = store.characterName(profile);
		SwingUtilities.invokeLater(() -> panel.setCharacter(name));
	}

	/**
	 * Logged out or switched: forget the character's goals and progress until the next login.
	 */
	private void clearCharacter()
	{
		progress = null;
		progressProfile = null;
		store.clearProgressCache();
		rates.clear();
		goals = Collections.emptyList();
		goalsProfile = null;
		SwingUtilities.invokeLater(() -> panel.setCharacter(null));
	}

	private void writeGoals(List<Goal> list)
	{
		String profile = goalsProfile;
		if (profile == null)
		{
			// Logged out; the panel doesn't offer changes then
			return;
		}
		goals = Collections.unmodifiableList(list);
		store.saveGoals(profile, list);
	}

	// Display

	private void requestIcon(Goal goal)
	{
		String key = goal.targetKey();
		if (key == null || !iconsRequested.add(key))
		{
			return;
		}

		if (goal.isXp())
		{
			icons.put(key, goal.isOverall() && !goal.isLevel()
				? ImageUtil.loadImageResource(DailyGoalsPlugin.class, "overall.png")
				: skillIconManager.getSkillImage(goal.getSkill()));
			return;
		}

		spriteManager.getSpriteAsync(goal.getActivity().getSpriteId(), 0, sprite ->
			clientThread.invokeLater(() ->
			{
				icons.put(key, sprite);
				update();
			}));
	}

	private void syncOverlays()
	{
		Set<String> wanted = new HashSet<>();
		for (Goal goal : goals)
		{
			if (config.show().isOverlays() && goal.isEnabled() && goal.isOverlay() && goal.targetKey() != null)
			{
				wanted.add(goal.getId());
				overlays.computeIfAbsent(goal.getId(), id ->
				{
					DailyGoalsOverlay overlay = new DailyGoalsOverlay(this, config, id);
					overlayManager.add(overlay);
					return overlay;
				});
			}
		}

		overlays.entrySet().removeIf(entry ->
		{
			if (wanted.contains(entry.getKey()))
			{
				return false;
			}
			overlayManager.remove(entry.getValue());
			return true;
		});
	}

	private void syncInfoBoxes()
	{
		Set<String> wanted = new HashSet<>();
		for (Goal goal : goals)
		{
			String key = goal.targetKey();
			BufferedImage icon = getIcon(goal);
			if (!config.show().isInfoboxes() || !goal.isEnabled() || !goal.isInfobox() || key == null || icon == null)
			{
				continue;
			}
			wanted.add(goal.getId());

			DailyGoalsInfoBox infoBox = infoBoxes.get(goal.getId());
			if (infoBox == null)
			{
				infoBox = new DailyGoalsInfoBox(icon, this, config, goal.getId(), key);
				infoBoxes.put(goal.getId(), infoBox);
				infoBoxManager.addInfoBox(infoBox);
			}
			else if (!key.equals(infoBox.getIconTarget()))
			{
				// The goal now counts something else; show its icon
				infoBox.setImage(icon);
				infoBox.setIconTarget(key);
				infoBoxManager.updateInfoBoxImage(infoBox);
			}
		}

		infoBoxes.entrySet().removeIf(entry ->
		{
			if (wanted.contains(entry.getKey()))
			{
				return false;
			}
			infoBoxManager.removeInfoBox(entry.getValue());
			return true;
		});
	}

	/**
	 * Send the panel fresh snapshots, if anything changed.
	 */
	private void updatePanel()
	{
		GoalSchedule schedule = GoalSchedule.of(config);
		List<GoalView> views = new ArrayList<>();
		for (Goal goal : goals)
		{
			GoalProgress goalProgress = getProgress(goal.getId());
			if (goalProgress == null)
			{
				views.add(GoalView.loggedOut(goal, getIcon(goal), baseColor(goal)));
			}
			else
			{
				GoalStatus status = status(goal, goalProgress, schedule);
				views.add(GoalView.of(status, getIcon(goal), barColor(status), schedule));
			}
		}

		if (!views.equals(shownViews))
		{
			shownViews = views;
			SwingUtilities.invokeLater(() -> panel.showGoals(views));
		}
	}

	private static Color baseColor(Goal goal)
	{
		if (!goal.isXp())
		{
			return COUNT_BAR_COLOR;
		}
		return goal.isOverall() && !goal.isLevel() ? OVERALL_BAR_COLOR : SkillColor.find(goal.getSkill()).getColor();
	}

	private void chat(String message)
	{
		if (!config.chatMessages())
		{
			return;
		}

		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.GAMEMESSAGE)
			.runeLiteFormattedMessage(new ChatMessageBuilder()
				.append(ChatColorType.HIGHLIGHT)
				.append(message)
				.build())
			.build());
	}
}

package com.dailygoals;

import net.runelite.client.util.QuantityFormatter;

/**
 * Number and time formatting shared by the overlay, infobox and panel.
 */
final class Formats
{
	private Formats()
	{
	}

	/**
	 * "12,345".
	 */
	static String number(long value)
	{
		return QuantityFormatter.formatNumber(value);
	}

	/**
	 * "12.3K", for small spaces like the infobox.
	 */
	static String shortNumber(long value)
	{
		return QuantityFormatter.quantityToStackSize(value);
	}

	/**
	 * {@code value} as a percentage of {@code target}: "45.0%".
	 */
	static String percent(long value, long target)
	{
		return String.format("%.1f%%", ratio(value, target));
	}

	/**
	 * Whole percent, rounded down so it doesn't read 100% before it's done: "45%", for the infobox.
	 */
	static String shortPercent(long value, long target)
	{
		return (long) Math.floor(ratio(value, target)) + "%";
	}

	/**
	 * "1h 23m", "23m", "<1m" or "5d"; "-" when unknown (negative).
	 */
	static String duration(long millis)
	{
		if (millis < 0)
		{
			return "-";
		}
		long minutes = millis / 60_000;
		if (minutes < 1)
		{
			return "<1m";
		}
		long hours = minutes / 60;
		if (hours >= 100)
		{
			return hours / 24 + "d";
		}
		return hours > 0 ? hours + "h " + minutes % 60 + "m" : minutes + "m";
	}

	/**
	 * "+12,000" ahead of pace or "-5,000" behind it.
	 */
	static String pace(long pace)
	{
		return (pace >= 0 ? "+" : "-") + number(Math.abs(pace));
	}

	/**
	 * Pace as a percentage of the target: "+12.0%" or "-5.0%".
	 */
	static String pacePercent(long pace, long target)
	{
		return (pace >= 0 ? "+" : "-") + percent(Math.abs(pace), target);
	}

	private static double ratio(long value, long target)
	{
		return target <= 0 ? 100 : 100.0 * value / target;
	}
}

package com.dailygoals;

import com.google.gson.annotations.SerializedName;
import java.text.ParseException;
import java.time.DayOfWeek;
import java.util.Locale;
import javax.annotation.Nullable;
import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;
import lombok.RequiredArgsConstructor;
import net.runelite.api.Experience;
import net.runelite.api.Skill;
import net.runelite.client.util.QuantityFormatter;

/**
 * One goal as the user set it up in the sidebar. The list of goals is stored as JSON in the
 * plugin's config and is shared by every account; progress is stored per account in
 * {@link GoalProgress}.
 */
@Data
@NoArgsConstructor
@AllArgsConstructor
class Goal
{
	static final int ALL_DAYS = 0b111_1111;

	@RequiredArgsConstructor
	enum Type
	{
		/** Gain an amount of XP in a skill, or in total. */
		XP("Gain XP"),
		/** Reach a level in a skill. */
		LEVEL("Reach a level"),
		/** Kill a boss or complete an activity a number of times. */
		@SerializedName(value = "COUNT", alternate = "KC")
		COUNT("Count");

		private final String label;

		@Override
		public String toString()
		{
			return label;
		}
	}

	@RequiredArgsConstructor
	enum Period
	{
		DAILY("Daily"),
		WEEKLY("Weekly");

		private final String label;

		@Override
		public String toString()
		{
			return label;
		}
	}

	String id;
	Type type = Type.XP;
	Skill skill = Skill.ATTACK;
	/** XP goal on total XP instead of {@link #skill}. */
	boolean overall;
	@SerializedName(value = "activity", alternate = "boss")
	Activity activity = Activity.ZULRAH;
	/** Name typed in for {@link Activity#OTHER}. */
	@SerializedName(value = "customName", alternate = "customBoss")
	String customName = "";
	/** XP or count per period; the target level for level goals. */
	int amount = 100_000;
	Period period = Period.DAILY;
	/** Days a daily goal counts on, one bit per day from Monday (bit 0) to Sunday (bit 6). */
	int days = ALL_DAYS;
	/** Switched off: still counted in the background, but no overlay, infobox or messages. */
	boolean enabled = true;
	boolean overlay = true;
	boolean infobox = true;

	Goal copy()
	{
		return new Goal(id, type, skill, overall, activity, customName, amount, period, days, enabled, overlay, infobox);
	}

	/** XP and level goals both follow XP. */
	boolean isXp()
	{
		return type != Type.COUNT;
	}

	boolean isLevel()
	{
		return type == Type.LEVEL;
	}

	boolean isWeekly()
	{
		return period == Period.WEEKLY;
	}

	boolean isActiveOn(DayOfWeek day)
	{
		return (days & (1 << (day.getValue() - 1))) != 0;
	}

	/**
	 * XP needed from {@code startXp} to reach the target level, for level goals.
	 */
	long xpToLevel(long startXp)
	{
		int level = Math.max(1, Math.min(Experience.MAX_VIRT_LEVEL, amount));
		return Math.max(0, Experience.getXpForLevel(level) - startXp);
	}

	/**
	 * Key for what the goal counts. Progress starts over when it changes. Null when the goal is
	 * {@link Activity#OTHER} with no name yet.
	 */
	@Nullable
	String targetKey()
	{
		String key;
		if (isLevel())
		{
			key = "level:" + skill.name() + ":" + amount;
		}
		else if (isXp())
		{
			key = "xp:" + (overall ? "OVERALL" : skill.name());
		}
		else if (activity != Activity.OTHER)
		{
			key = "kc:" + activity.name();
		}
		else
		{
			String custom = Activity.normalize(customName());
			if (custom.isEmpty())
			{
				return null;
			}
			key = "kc:other:" + custom;
		}
		return isWeekly() ? key + ":weekly" : key;
	}

	/**
	 * Whether a count read from a game message belongs to this goal.
	 */
	boolean counts(CountMessage count)
	{
		if (isXp())
		{
			return false;
		}

		switch (count.getKind())
		{
			case KILL:
				if (activity == Activity.OTHER)
				{
					String custom = Activity.normalize(customName());
					return !custom.isEmpty() && custom.equals(Activity.normalize(count.getName()));
				}
				return activity.matches(count.getName());
			case CLUE:
				return count.getName().equals(activity.clueTier());
			default:
				return activity.getKind() == count.getKind();
		}
	}

	/**
	 * What the goal counts, e.g. "Attack XP", "Level 80 Mining" or "Zulrah kills".
	 */
	String name()
	{
		if (isLevel())
		{
			return "Level " + amount + " " + skill.getName();
		}
		if (isXp())
		{
			return (overall ? "Overall" : skill.getName()) + " XP";
		}
		return activity.goalName(customName().trim());
	}

	String rateLabel()
	{
		if (isXp())
		{
			return "XP/h";
		}
		return activity.getKind() == Activity.Kind.KILL ? "Kills/h" : "Per hour";
	}

	private String customName()
	{
		return customName == null ? "" : customName;
	}

	/**
	 * Parse an amount such as "250,000", "150k" or "1.5m". Null if it isn't a usable amount.
	 */
	@Nullable
	static Integer parseAmount(String text)
	{
		try
		{
			long amount = QuantityFormatter.parseQuantity(text.replace(",", "").replace(" ", "").toLowerCase(Locale.ROOT));
			return amount >= 1 && amount <= Integer.MAX_VALUE ? (int) amount : null;
		}
		catch (ParseException | NumberFormatException e)
		{
			return null;
		}
	}
}

package com.dailygoals;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.function.Consumer;
import javax.swing.ImageIcon;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JToggleButton;
import javax.swing.SwingConstants;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.DynamicGridLayout;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.components.ProgressBar;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.SwingUtil;

/**
 * One goal in the sidebar: icon and name with on/off switch and reorder arrows, a progress bar,
 * the numbers, a history chart, and Edit / Reset / Remove buttons.
 * <p>
 * The card is built for one {@link Goal} and updated with fresh {@link GoalView}s; the panel
 * builds new cards when the goals themselves change.
 */
class GoalCard extends JPanel
{
	private static final int ICON_SIZE = 25;
	private static final ImageIcon UP_ICON = PanelStyle.arrowIcon(true);
	private static final ImageIcon DOWN_ICON = PanelStyle.arrowIcon(false);
	// Same look as the plugin list's on/off switch
	private static final BufferedImage SWITCH_IMAGE = ImageUtil.loadImageResource(GoalCard.class, "switcher_on.png");
	private static final ImageIcon SWITCH_ON = new ImageIcon(SWITCH_IMAGE);
	private static final ImageIcon SWITCH_OFF = new ImageIcon(ImageUtil.flipImage(
		ImageUtil.luminanceScale(ImageUtil.grayscaleImage(SWITCH_IMAGE), 0.61f), true, false));

	private final boolean enabled;
	private final JLabel icon = new JLabel();
	private final ProgressBar progressBar = new ProgressBar();
	private final JLabel doneValue = PanelStyle.valueLabel();
	private final JLabel leftKey = PanelStyle.smallLabel("Left:");
	private final JLabel leftValue = PanelStyle.valueLabel();
	private final JLabel rateKey = PanelStyle.smallLabel("XP/h:");
	private final JLabel rateValue = PanelStyle.valueLabel();
	private final JLabel etaValue = PanelStyle.valueLabel();
	private final JLabel paceValue = PanelStyle.valueLabel();
	private final JLabel streakValue = PanelStyle.valueLabel();
	private final HistoryChart chart = new HistoryChart();
	private final JLabel notes = PanelStyle.smallLabel(" ");
	private final JButton editButton = PanelStyle.smallButton("Edit");
	private final JButton resetButton = PanelStyle.smallButton("Reset");
	private BufferedImage shownIcon;

	/**
	 * @param onEdit called when Edit is clicked; the panel opens the editor, or saves it when
	 *               this goal is already open
	 */
	GoalCard(DailyGoalsPlugin plugin, Goal goal, int index, int count, Consumer<Goal> onEdit)
	{
		enabled = goal.isEnabled();
		setLayout(new DynamicGridLayout(0, 1, 0, 5));
		setBackground(ColorScheme.DARKER_GRAY_COLOR);
		setBorder(new EmptyBorder(8, 8, 8, 8));

		progressBar.setBackground(ColorScheme.DARK_GRAY_COLOR);
		progressBar.setMaximumValue(1000);

		JPanel stats = new JPanel(new DynamicGridLayout(0, 1, 0, 2));
		stats.setOpaque(false);
		stats.add(PanelStyle.statRow(PanelStyle.smallLabel("Done:"), doneValue));
		stats.add(PanelStyle.statRow(leftKey, leftValue));
		stats.add(PanelStyle.statRow(rateKey, rateValue));
		stats.add(PanelStyle.statRow(PanelStyle.smallLabel("Done in:"), etaValue));
		stats.add(PanelStyle.statRow(PanelStyle.smallLabel("Pace:"), paceValue));
		stats.add(PanelStyle.statRow(PanelStyle.smallLabel("Streak:"), streakValue));

		editButton.addActionListener(e -> onEdit.accept(goal));
		resetButton.setToolTipText("Start this period's count over from now");
		resetButton.addActionListener(e -> plugin.restartPeriod(goal.getId()));
		JButton removeButton = PanelStyle.smallButton("Remove");
		removeButton.addActionListener(e ->
		{
			int choice = JOptionPane.showConfirmDialog(this, "Remove the goal \"" + goal.name() + "\"?",
				"Daily Goals", JOptionPane.YES_NO_OPTION);
			if (choice == JOptionPane.YES_OPTION)
			{
				plugin.removeGoal(goal.getId());
			}
		});
		JPanel buttons = new JPanel(new GridLayout(1, 3, 4, 0));
		buttons.setOpaque(false);
		buttons.add(editButton);
		buttons.add(resetButton);
		buttons.add(removeButton);

		add(header(plugin, goal, index, count));
		add(progressBar);
		add(stats);
		add(PanelStyle.smallLabel(goal.isWeekly() ? "Last 30 weeks" : "Last 30 days"));
		add(chart);
		add(notes);
		add(buttons);
		setEditing(false);
	}

	private JPanel header(DailyGoalsPlugin plugin, Goal goal, int index, int count)
	{
		icon.setPreferredSize(new Dimension(ICON_SIZE, ICON_SIZE));
		icon.setHorizontalAlignment(SwingConstants.CENTER);

		JLabel name = new JLabel(goal.name());
		name.setFont(FontManager.getRunescapeBoldFont());
		name.setForeground(enabled ? Color.WHITE : ColorScheme.MEDIUM_GRAY_COLOR);
		name.setToolTipText(goal.name() + (goal.isWeekly() ? " (weekly)" : ""));

		JToggleButton toggle = new JToggleButton(SWITCH_OFF, enabled);
		toggle.setSelectedIcon(SWITCH_ON);
		toggle.setToolTipText(enabled ? "Turn this goal off" : "Turn this goal on");
		SwingUtil.removeButtonDecorations(toggle);
		toggle.addActionListener(e -> plugin.setGoalEnabled(goal.getId(), toggle.isSelected()));

		JButton up = PanelStyle.iconButton(UP_ICON, "Move up", index > 0);
		up.addActionListener(e -> plugin.moveGoal(goal.getId(), -1));
		JButton down = PanelStyle.iconButton(DOWN_ICON, "Move down", index < count - 1);
		down.addActionListener(e -> plugin.moveGoal(goal.getId(), 1));
		JPanel arrows = new JPanel(new GridLayout(1, 2, 2, 0));
		arrows.setOpaque(false);
		arrows.add(up);
		arrows.add(down);

		JPanel controls = new JPanel(new BorderLayout(4, 0));
		controls.setOpaque(false);
		controls.add(toggle, BorderLayout.WEST);
		controls.add(arrows, BorderLayout.EAST);

		JPanel header = new JPanel(new BorderLayout(6, 0));
		header.setOpaque(false);
		header.add(icon, BorderLayout.WEST);
		header.add(name, BorderLayout.CENTER);
		header.add(controls, BorderLayout.EAST);
		return header;
	}

	/**
	 * While this goal is in the editor, Edit reads Save.
	 */
	void setEditing(boolean editing)
	{
		editButton.setText(editing ? "Save" : "Edit");
		editButton.setToolTipText(editing ? "Save and close the editor" : "Edit this goal");
	}

	void update(GoalView view)
	{
		if (view.getIcon() != shownIcon)
		{
			shownIcon = view.getIcon();
			icon.setIcon(shownIcon == null ? null : new ImageIcon(ImageUtil.resizeImage(shownIcon, ICON_SIZE, ICON_SIZE)));
		}

		updateProgressBar(view);
		updateStats(view);
		chart.setBars(view.getHistory(), view.getColor());
		resetButton.setEnabled(view.isTracking());

		List<String> lines = new ArrayList<>();
		if (view.getWeekendPercent() > 0)
		{
			lines.add("Weekend goal: " + view.getWeekendPercent() + "%");
		}
		if (view.getExtra() > 0)
		{
			lines.add("Carried over: " + Formats.number(view.getExtra()));
		}
		else if (view.getMissed() > 0)
		{
			lines.add("Missed last time, added: " + Formats.number(view.getMissed()));
		}
		notes.setText(lines.isEmpty() ? " " : "<html>" + String.join("<br>", lines) + "</html>");
	}

	private void updateProgressBar(GoalView view)
	{
		boolean live = view.isTracking() && view.isActive() && enabled;
		int permille = view.getTarget() <= 0 ? 1000 : (int) Math.min(1000, view.getDone() * 1000 / view.getTarget());

		progressBar.setForeground(view.getColor());
		progressBar.setValue(view.isTracking() ? permille : 0);
		progressBar.setLeftLabel("0");
		progressBar.setRightLabel(Formats.shortNumber(view.getTarget()));
		progressBar.setCenterLabel(centerLabel(view));
		// A tick where an even pace would be
		progressBar.setPositions(live && !view.isComplete()
			? Collections.singletonList(Math.max(1, Math.min(999, view.getPacePermille())))
			: Collections.emptyList());
		progressBar.setDimmedText(!enabled ? "Off" : !view.isTracking() ? "Not logged in" : "Rest day");
		progressBar.setDimmed(!live);
	}

	private void updateStats(GoalView view)
	{
		rateKey.setText(view.getGoal().rateLabel() + ":");
		leftValue.setForeground(view.isComplete() ? PanelStyle.GOOD : Color.WHITE);

		if (!view.isTracking())
		{
			for (JLabel label : new JLabel[]{doneValue, leftValue, rateValue, etaValue, paceValue, streakValue})
			{
				label.setText("-");
			}
			paceValue.setForeground(Color.WHITE);
			return;
		}

		doneValue.setText(Formats.number(view.getDone()) + " / " + Formats.number(view.getTarget()));
		if (view.getOver() > 0)
		{
			leftKey.setText("Over:");
			leftValue.setText("+" + Formats.number(view.getOver()));
		}
		else
		{
			leftKey.setText("Left:");
			leftValue.setText(view.isComplete() ? "Done" : Formats.number(view.getLeft()));
		}
		rateValue.setText(Formats.number(view.getRate()));
		etaValue.setText(view.isComplete() ? "Done" : Formats.duration(view.getEtaMillis()));

		if (view.isComplete() || !view.isActive())
		{
			paceValue.setText(view.isComplete() ? "Done" : "Rest day");
			paceValue.setForeground(PanelStyle.GOOD);
		}
		else
		{
			paceValue.setText(Formats.pace(view.getPace()));
			paceValue.setForeground(view.getPace() >= 0 ? PanelStyle.GOOD : DailyGoalsPlugin.BEHIND_PACE_COLOR);
		}

		String best = view.getBestStreak() > view.getStreak() ? " (best " + view.getBestStreak() + ")" : "";
		streakValue.setText(view.getStreak() + best);
	}

	private static String centerLabel(GoalView view)
	{
		if (view.getOver() > 0 && view.getTarget() > 0)
		{
			return String.format("+%.1f%%", 100.0 * view.getOver() / view.getTarget());
		}
		if (view.isComplete())
		{
			return "Done!";
		}
		return String.format("%.1f%%", view.getTarget() <= 0 ? 100 : 100.0 * view.getDone() / view.getTarget());
	}
}

package com.dailygoals;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.GridLayout;
import java.util.function.Consumer;
import javax.annotation.Nullable;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTextField;
import javax.swing.JToggleButton;
import javax.swing.border.EmptyBorder;
import net.runelite.api.Experience;
import net.runelite.api.Skill;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.DynamicGridLayout;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.QuantityFormatter;

/**
 * The form to add or edit a goal. Rows that don't apply (the XP/level choice, the custom name,
 * the days) are swapped in and out as the choices change.
 */
class GoalEditor extends JPanel
{
	private static final int DEFAULT_XP_AMOUNT = 100_000;
	private static final int DEFAULT_COUNT_AMOUNT = 10;
	private static final int DEFAULT_LEVEL = 99;
	private static final String[] DAY_LETTERS = {"M", "T", "W", "T", "F", "S", "S"};
	private static final String[] DAY_NAMES = {"Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"};

	private final Consumer<Goal> onSave;
	private final Runnable onCancel;

	private final JLabel title = PanelStyle.heading("", ColorScheme.BRAND_ORANGE);
	private final TargetPicker targetPicker;
	private final JComboBox<Goal.Type> xpTypeBox = new JComboBox<>(new Goal.Type[]{Goal.Type.XP, Goal.Type.LEVEL});
	private final JTextField customNameInput = new JTextField();
	private final JLabel amountLabel = PanelStyle.smallLabel("");
	private final JTextField amountField = new JTextField();
	private final JComboBox<Goal.Period> periodBox = new JComboBox<>(Goal.Period.values());
	private final JToggleButton[] dayButtons = new JToggleButton[7];
	private final JCheckBox infoboxCheck = new JCheckBox("Show infobox (amount left)");
	private final JCheckBox overlayCheck = new JCheckBox("Show overlay");
	private final JLabel error = PanelStyle.smallLabel("");

	/** Rows that come and go: the XP/level choice or the custom name. */
	private final JPanel targetRows = new JPanel(new DynamicGridLayout(0, 1, 0, 6));
	/** "Repeats", plus the days for daily goals. */
	private final JPanel scheduleRows = new JPanel(new DynamicGridLayout(0, 1, 0, 6));
	private final JPanel xpTypeField = PanelStyle.field("Goal", xpTypeBox);
	private final JPanel customNameField = PanelStyle.field("Boss name (as in the kill count message)", customNameInput);
	private final JPanel periodField = PanelStyle.field("Repeats", periodBox);
	private final JPanel daysField;

	/** The goal being edited (a copy), or null when the form is closed. */
	@Nullable
	private Goal editing;

	GoalEditor(SkillIconManager skillIconManager, SpriteManager spriteManager, Consumer<Goal> onSave, Runnable onCancel)
	{
		this.onSave = onSave;
		this.onCancel = onCancel;
		this.targetPicker = new TargetPicker(skillIconManager, spriteManager);

		setLayout(new DynamicGridLayout(0, 1, 0, 6));
		setBackground(ColorScheme.DARKER_GRAY_COLOR);
		setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 2, 0, 0, ColorScheme.BRAND_ORANGE),
			new EmptyBorder(8, 8, 8, 8)));

		JPanel days = new JPanel(new GridLayout(1, 7, 2, 0));
		days.setOpaque(false);
		for (int i = 0; i < 7; i++)
		{
			DayButton day = new DayButton(DAY_LETTERS[i], DAY_NAMES[i]);
			dayButtons[i] = day;
			days.add(day);
		}
		daysField = PanelStyle.field("On these days", days);

		targetPicker.addActionListener(e -> onTypeChanged());
		xpTypeBox.addActionListener(e -> onTypeChanged());
		periodBox.addActionListener(e -> updateRows());
		amountField.addActionListener(e -> save());
		customNameInput.addActionListener(e -> save());
		infoboxCheck.setOpaque(false);
		overlayCheck.setOpaque(false);
		error.setForeground(ColorScheme.PROGRESS_ERROR_COLOR);

		JPanel amount = new JPanel(new BorderLayout(0, 2));
		amount.setOpaque(false);
		amount.add(amountLabel, BorderLayout.NORTH);
		amount.add(amountField, BorderLayout.CENTER);

		JButton saveButton = PanelStyle.smallButton("Save");
		saveButton.addActionListener(e -> save());
		JButton cancelButton = PanelStyle.smallButton("Cancel");
		cancelButton.addActionListener(e -> onCancel.run());
		JPanel buttons = new JPanel(new GridLayout(1, 2, 6, 0));
		buttons.setOpaque(false);
		buttons.add(saveButton);
		buttons.add(cancelButton);

		targetRows.setOpaque(false);
		scheduleRows.setOpaque(false);
		add(title);
		add(PanelStyle.field("Track", targetPicker));
		add(targetRows);
		add(amount);
		add(scheduleRows);
		add(infoboxCheck);
		add(overlayCheck);
		add(error);
		add(buttons);
	}

	/**
	 * Fill the form from a goal, or with defaults for a new one.
	 */
	void open(@Nullable Goal goal)
	{
		editing = goal == null ? new Goal() : goal.copy();
		title.setText(goal == null ? "New goal" : "Edit goal");

		targetPicker.select(editing);
		xpTypeBox.setSelectedItem(editing.isLevel() ? Goal.Type.LEVEL : Goal.Type.XP);
		customNameInput.setText(editing.getCustomName());
		amountField.setText(editing.isLevel() ? String.valueOf(editing.getAmount()) : QuantityFormatter.formatNumber(editing.getAmount()));
		periodBox.setSelectedItem(editing.getPeriod());
		for (int i = 0; i < 7; i++)
		{
			dayButtons[i].setSelected((editing.getDays() & (1 << i)) != 0);
		}
		infoboxCheck.setSelected(editing.isInfobox());
		overlayCheck.setSelected(editing.isOverlay());
		error.setText("");
		updateRows();
	}

	boolean isEditing(String goalId)
	{
		return editing != null && goalId.equals(editing.getId());
	}

	void close()
	{
		editing = null;
	}

	/**
	 * Check the form and hand the goal to {@code onSave}; shows an error instead if something's off.
	 */
	void save()
	{
		if (editing == null)
		{
			return;
		}

		Goal.Type type = selectedType();
		Skill skill = targetPicker.selectedSkill();
		Activity activity = targetPicker.selectedActivity();
		String customName = customNameInput.getText().trim();
		Goal.Period period = (Goal.Period) periodBox.getSelectedItem();
		Integer amount = Goal.parseAmount(amountField.getText());
		int days = selectedDays();

		String problem = problem(type, skill, activity, customName, amount, period, days);
		if (problem != null)
		{
			error.setText("<html>" + problem + "</html>");
			return;
		}

		editing.setType(type);
		editing.setOverall(type == Goal.Type.XP && skill == null);
		if (skill != null)
		{
			editing.setSkill(skill);
		}
		if (activity != null)
		{
			editing.setActivity(activity);
		}
		editing.setCustomName(customName);
		editing.setAmount(amount);
		editing.setPeriod(period);
		editing.setDays(period == Goal.Period.DAILY ? days : Goal.ALL_DAYS);
		editing.setInfobox(infoboxCheck.isSelected());
		editing.setOverlay(overlayCheck.isSelected());
		onSave.accept(editing);
	}

	@Nullable
	private static String problem(Goal.Type type, @Nullable Skill skill, @Nullable Activity activity, String customName,
		@Nullable Integer amount, Goal.Period period, int days)
	{
		if (type == Goal.Type.LEVEL)
		{
			if (skill == null)
			{
				return "Reach a level needs a skill, not Overall.";
			}
			if (amount == null || amount < 2 || amount > Experience.MAX_VIRT_LEVEL)
			{
				return "Enter a level from 2 to " + Experience.MAX_VIRT_LEVEL + ".";
			}
		}
		else if (amount == null)
		{
			return "Enter an amount, like 150000 or 150k.";
		}

		if (activity == Activity.OTHER && customName.isEmpty())
		{
			return "Type the boss name.";
		}
		if (period == Goal.Period.DAILY && days == 0)
		{
			return "Pick at least one day.";
		}
		return null;
	}

	/**
	 * A boss or activity is a count; a skill is XP or a level, as picked.
	 */
	private Goal.Type selectedType()
	{
		if (targetPicker.isActivitySelected())
		{
			return Goal.Type.COUNT;
		}
		return xpTypeBox.getSelectedItem() == Goal.Type.LEVEL ? Goal.Type.LEVEL : Goal.Type.XP;
	}

	private int selectedDays()
	{
		int days = 0;
		for (int i = 0; i < 7; i++)
		{
			days |= dayButtons[i].isSelected() ? 1 << i : 0;
		}
		return days;
	}

	private void onTypeChanged()
	{
		// Swap an untouched default amount for one that suits the goal type
		Integer amount = Goal.parseAmount(amountField.getText());
		boolean untouched = amount != null && (amount == DEFAULT_XP_AMOUNT || amount == DEFAULT_COUNT_AMOUNT || amount == DEFAULT_LEVEL);
		if (untouched)
		{
			switch (selectedType())
			{
				case LEVEL:
					amountField.setText(String.valueOf(DEFAULT_LEVEL));
					break;
				case COUNT:
					amountField.setText(String.valueOf(DEFAULT_COUNT_AMOUNT));
					break;
				default:
					amountField.setText(QuantityFormatter.formatNumber(DEFAULT_XP_AMOUNT));
					break;
			}
		}
		updateRows();
	}

	private void updateRows()
	{
		Goal.Type type = selectedType();
		boolean weekly = periodBox.getSelectedItem() == Goal.Period.WEEKLY;

		targetRows.removeAll();
		if (type != Goal.Type.COUNT)
		{
			targetRows.add(xpTypeField);
		}
		else if (targetPicker.selectedActivity() == Activity.OTHER)
		{
			targetRows.add(customNameField);
		}

		scheduleRows.removeAll();
		scheduleRows.add(periodField);
		if (!weekly)
		{
			scheduleRows.add(daysField);
		}

		if (type == Goal.Type.LEVEL)
		{
			amountLabel.setText("Target level");
			amountField.setToolTipText("The level to reach, 2 to " + Experience.MAX_VIRT_LEVEL);
		}
		else
		{
			amountLabel.setText(weekly ? "Weekly amount" : "Daily amount");
			amountField.setToolTipText("XP or count per " + (weekly ? "week" : "day") + ". Shorthand works: 150k, 1.5m");
		}

		revalidate();
		repaint();
	}

	/**
	 * A day toggle painted green when the goal counts that day and red when it doesn't. Painted
	 * by hand because the client's look and feel ignores toggle button background colours.
	 */
	private static class DayButton extends JToggleButton
	{
		private static final Color ON = new Color(46, 125, 50);
		private static final Color OFF = new Color(140, 45, 45);

		private final String dayName;

		DayButton(String letter, String dayName)
		{
			super(letter, true);
			this.dayName = dayName;
			setFont(FontManager.getRunescapeSmallFont());
			setFocusPainted(false);
			setRolloverEnabled(true);
			setPreferredSize(new Dimension(20, 18));
			updateTooltip();
			addItemListener(e -> updateTooltip());
		}

		private void updateTooltip()
		{
			setToolTipText(dayName + ": " + (isSelected() ? "on" : "off"));
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			Color color = isSelected() ? ON : OFF;
			g.setColor(getModel().isRollover() ? color.brighter() : color);
			g.fillRect(0, 0, getWidth(), getHeight());

			g.setFont(getFont());
			g.setColor(Color.WHITE);
			FontMetrics metrics = g.getFontMetrics();
			int x = (getWidth() - metrics.stringWidth(getText())) / 2;
			int y = (getHeight() - metrics.getHeight()) / 2 + metrics.getAscent();
			g.drawString(getText(), x, y);
		}

		@Override
		protected void paintBorder(Graphics g)
		{
			// The colour is the border
		}
	}
}

package com.dailygoals;

import java.util.ArrayList;
import java.util.List;

/**
 * One account's progress on a goal for the current period (day or week), plus its streak and
 * history. Stored as JSON per RuneScape profile, so field names must not change.
 */
class GoalProgress
{
	static final int HISTORY_SIZE = 60;

	/** {@link Goal#targetKey()} this progress belongs to; when the goal changes, progress starts over. */
	String target;
	/** Epoch millis of the reset that started the current period. */
	long day;
	/** XP or count when the period started; null until first seen. */
	Long baseline;
	/** Gained since the period started. */
	long gained;
	/** Progress carried in from the previous period. */
	long extra;
	/** Unfinished amount carried in from the previous period, added to the goal. */
	long missed;
	/** Whether this period's completion has been announced. */
	boolean completed;
	/** Highest milestone percentage (50, 75) announced this period. */
	int milestone;
	/** Finished periods in a row that reached the goal. */
	int streak;
	int bestStreak;
	/** Finished periods the goal counted in, oldest first. */
	List<PeriodResult> history = new ArrayList<>();

	/**
	 * How one finished period went.
	 */
	static class PeriodResult
	{
		long day;
		long done;
		long goal;

		PeriodResult()
		{
		}

		PeriodResult(long day, long done, long goal)
		{
			this.day = day;
			this.done = done;
			this.goal = goal;
		}

		boolean isDone()
		{
			return done >= goal;
		}
	}

	// For Gson, so the field defaults above apply to older saves
	GoalProgress()
	{
	}

	GoalProgress(String target, long day)
	{
		this.target = target;
		this.day = day;
	}

	long progress()
	{
		return gained + extra;
	}

	long goal(long amount)
	{
		return amount + missed;
	}

	long left(long amount)
	{
		return Math.max(0, goal(amount) - progress());
	}

	/**
	 * How far past the goal progress is.
	 */
	long over(long amount)
	{
		return Math.max(0, progress() - goal(amount));
	}

	boolean isDone(long amount)
	{
		return progress() >= goal(amount);
	}

	/**
	 * The streak including this period, once this period is done.
	 */
	int currentStreak(long amount, boolean active)
	{
		return streak + (active && isDone(amount) ? 1 : 0);
	}

	/**
	 * Record the current XP in the goal's skill.
	 */
	void observeXp(long xp)
	{
		if (baseline == null)
		{
			baseline = xp;
		}
		gained = Math.max(0, xp - baseline);
	}

	/**
	 * Record a running total from a game message. The first one seen this period counts as one.
	 */
	void observeTotal(long total)
	{
		if (baseline == null)
		{
			baseline = total - 1;
		}
		gained = Math.max(gained, total - baseline);
	}

	/**
	 * Count something whose message has no running total.
	 */
	void add(long count)
	{
		gained += count;
	}

	/**
	 * Start this period's count over from the next value seen. The streak and history stay.
	 */
	void restartPeriod()
	{
		baseline = null;
		gained = 0;
		completed = false;
		milestone = 0;
	}

	/**
	 * Start a new period. The next baseline is the last value seen, so anything gained while the
	 * client was closed counts toward the new period.
	 *
	 * @param amount      the goal amount for the period that just ended
	 * @param endedActive whether the goal counted in the period that ended; rest days pass any
	 *                    carry-over on unchanged and don't touch the streak
	 * @param skipped     whether a period the goal counts in was skipped entirely, which ends the streak
	 */
	void rollover(long newDay, long amount, DailyGoalsConfig.CarryOver carryOver, boolean endedActive, boolean skipped)
	{
		if (endedActive)
		{
			long target = goal(amount);
			history.add(new PeriodResult(day, progress(), target));
			while (history.size() > HISTORY_SIZE)
			{
				history.remove(0);
			}

			streak = progress() >= target ? streak + 1 : 0;

			long leftover = progress() - target;
			extra = carryOver.isCarryExtra() && leftover > 0 ? leftover : 0;
			missed = carryOver.isCarryMissed() && leftover < 0 ? -leftover : 0;
		}
		bestStreak = Math.max(bestStreak, streak);
		if (skipped)
		{
			streak = 0;
		}

		if (baseline != null)
		{
			baseline += gained;
		}
		gained = 0;
		completed = false;
		milestone = 0;
		day = newDay;
	}
}

package com.dailygoals;

import java.time.DayOfWeek;
import java.time.Instant;
import java.time.LocalDate;
import java.time.LocalTime;
import java.time.ZoneId;
import java.time.ZonedDateTime;
import java.time.format.DateTimeFormatter;
import java.time.temporal.TemporalAdjusters;
import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.RequiredArgsConstructor;

/**
 * A goal's periods (days or weeks) under the current reset settings. A period is identified by
 * the epoch millis it starts at. DST gaps are handled by {@link ZonedDateTime#of}, which moves
 * a missing reset time forward.
 */
@RequiredArgsConstructor
final class GoalSchedule
{
	private static final long DAY = 86_400_000L;
	private static final DateTimeFormatter DAY_FORMAT = DateTimeFormatter.ofPattern("EEE d MMM", Locale.ENGLISH);
	private static final DateTimeFormatter WEEK_FORMAT = DateTimeFormatter.ofPattern("'Week of' d MMM", Locale.ENGLISH);
	// "6", "06:30", "6.30", "0630"
	private static final Pattern TIME = Pattern.compile("(\\d{1,2})(?:[:.]?(\\d{2}))?");

	private final ZoneId zone;
	private final LocalTime resetTime;
	private final DayOfWeek weeklyResetDay;

	static GoalSchedule of(DailyGoalsConfig config)
	{
		return new GoalSchedule(config.timeZone().zone(), parseTime(config.resetTime()), config.weeklyResetDay().getDayOfWeek());
	}

	long periodStart(Goal goal, long at)
	{
		ZonedDateTime now = Instant.ofEpochMilli(at).atZone(zone);
		return goal.isWeekly() ? lastWeeklyReset(now, resetTime, weeklyResetDay) : lastDailyReset(now, resetTime);
	}

	long nextPeriodStart(Goal goal, long start)
	{
		// Half a day past a full period is safely inside the next one, DST or not
		return periodStart(goal, start + (goal.isWeekly() ? 7 * DAY : DAY) + DAY / 2);
	}

	long previousPeriodStart(Goal goal, long start)
	{
		return periodStart(goal, start - 1);
	}

	/**
	 * Whether the goal counts in the period starting at {@code start}; daily goals can skip days.
	 */
	boolean isActive(Goal goal, long start)
	{
		return goal.isWeekly() || goal.isActiveOn(dayOfWeek(start));
	}

	/**
	 * Whether the daily period starting at {@code start} is a Saturday or Sunday.
	 */
	boolean isWeekend(long start)
	{
		DayOfWeek day = dayOfWeek(start);
		return day == DayOfWeek.SATURDAY || day == DayOfWeek.SUNDAY;
	}

	/**
	 * How far through the period {@code now} is, 0 to 1.
	 */
	double elapsedFraction(Goal goal, long start, long now)
	{
		long end = nextPeriodStart(goal, start);
		double fraction = (now - start) / (double) (end - start);
		return Math.max(0, Math.min(1, fraction));
	}

	/**
	 * Whether a period the goal counts in lies strictly between two periods, i.e. was skipped.
	 */
	boolean missedBetween(Goal goal, long ended, long next)
	{
		int guard = 0;
		for (long p = nextPeriodStart(goal, ended); p < next && guard++ < 1000; p = nextPeriodStart(goal, p))
		{
			if (isActive(goal, p))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * "Thu 22 Oct", or "Week of 20 Oct" for weekly goals.
	 */
	String label(Goal goal, long start)
	{
		return (goal.isWeekly() ? WEEK_FORMAT : DAY_FORMAT).format(Instant.ofEpochMilli(start).atZone(zone));
	}

	private DayOfWeek dayOfWeek(long start)
	{
		return Instant.ofEpochMilli(start).atZone(zone).getDayOfWeek();
	}

	/**
	 * Epoch millis of the most recent daily reset at or before {@code now}.
	 */
	static long lastDailyReset(ZonedDateTime now, LocalTime time)
	{
		ZonedDateTime reset = ZonedDateTime.of(now.toLocalDate(), time, now.getZone());
		if (reset.isAfter(now))
		{
			reset = ZonedDateTime.of(now.toLocalDate().minusDays(1), time, now.getZone());
		}
		return reset.toInstant().toEpochMilli();
	}

	/**
	 * Epoch millis of the most recent weekly reset (on {@code day} at {@code time}) at or before {@code now}.
	 */
	static long lastWeeklyReset(ZonedDateTime now, LocalTime time, DayOfWeek day)
	{
		LocalDate date = now.toLocalDate().with(TemporalAdjusters.previousOrSame(day));
		ZonedDateTime reset = ZonedDateTime.of(date, time, now.getZone());
		if (reset.isAfter(now))
		{
			reset = ZonedDateTime.of(date.minusWeeks(1), time, now.getZone());
		}
		return reset.toInstant().toEpochMilli();
	}

	/**
	 * Parse the reset time setting. Anything unreadable means midnight.
	 */
	static LocalTime parseTime(String text)
	{
		Matcher matcher = TIME.matcher(text == null ? "" : text.trim());
		if (!matcher.matches())
		{
			return LocalTime.MIDNIGHT;
		}

		int hour = Integer.parseInt(matcher.group(1));
		int minute = matcher.group(2) == null ? 0 : Integer.parseInt(matcher.group(2));
		if (hour > 23 || minute > 59)
		{
			return LocalTime.MIDNIGHT;
		}
		return LocalTime.of(hour, minute);
	}
}

package com.dailygoals;

import lombok.Value;

/**
 * A goal's numbers right now, worked out from its progress. Used by the overlay, infobox,
 * announcements and panel.
 */
@Value
class GoalStatus
{
	Goal goal;
	GoalProgress progress;
	/** The goal amount for this period before carry-over (weekend multiplier applied). */
	long amount;
	/** False on a day the goal doesn't count. */
	boolean active;
	long done;
	/** The amount plus anything missed last period. */
	long target;
	long left;
	long over;
	boolean complete;
	/** XP or count per hour this login. */
	long rate;
	/** Time to reach the goal at the current rate; -1 when unknown. */
	long etaMillis;
	/** Ahead (positive) or behind (negative) an even pace that finishes at the reset. */
	long pace;
	/** How far through the period an even pace is, 0 to 1. */
	double paceFraction;
	int streak;
	/** The weekend multiplier in percent when it applies to this period, otherwise 0. */
	int weekendPercent;

	static GoalStatus of(Goal goal, GoalProgress progress, GoalSchedule schedule, int weekendMultiplier, long rate, long now)
	{
		int weekendPercent = weekendPercent(goal, progress, schedule, weekendMultiplier);
		long amount = amount(goal, progress, weekendPercent);
		boolean active = schedule.isActive(goal, progress.day);
		long target = progress.goal(amount);
		long left = progress.left(amount);
		long eta = left > 0 && rate > 0 ? left * 3_600_000L / rate : -1;
		double paceFraction = schedule.elapsedFraction(goal, progress.day, now);
		long pace = progress.progress() - (long) (paceFraction * target);
		return new GoalStatus(goal, progress, amount, active, progress.progress(), target, left, progress.over(amount),
			progress.isDone(amount), rate, eta, pace, paceFraction, progress.currentStreak(amount, active), weekendPercent);
	}

	/**
	 * The goal amount for the progress's period. Level goals need the XP from the period start to
	 * the target level; daily goals are scaled on weekends.
	 */
	static long amount(Goal goal, GoalProgress progress, int weekendPercent)
	{
		if (goal.isLevel())
		{
			// Not seen yet: avoid reading as already reached
			return progress.baseline == null ? 1 : goal.xpToLevel(progress.baseline);
		}
		return weekendPercent == 0 ? goal.getAmount() : Math.max(1, (long) goal.getAmount() * weekendPercent / 100);
	}

	/**
	 * The weekend multiplier in percent when it applies to the progress's period, otherwise 0.
	 * It only applies to daily XP and count goals.
	 */
	static int weekendPercent(Goal goal, GoalProgress progress, GoalSchedule schedule, int weekendMultiplier)
	{
		boolean applies = weekendMultiplier != 100 && !goal.isWeekly() && !goal.isLevel() && schedule.isWeekend(progress.day);
		return applies ? weekendMultiplier : 0;
	}

	boolean isBehind()
	{
		return active && !complete && pace < 0;
	}

	/**
	 * Progress as a percentage of the target; goes past 100 when over.
	 */
	double percent()
	{
		return target <= 0 ? 100 : 100.0 * done / target;
	}
}

package com.dailygoals;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.google.gson.reflect.TypeToken;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Skill;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.RuneScapeProfile;
import net.runelite.client.config.RuneScapeProfileType;
import net.runelite.client.util.Text;

/**
 * Reads and writes the plugin's data in RuneLite's config. Each character (RuneScape profile)
 * has its own goals and progress.
 */
@Slf4j
@Singleton
class GoalStore
{
	static final String GOALS_KEY = "goals";
	static final String PROGRESS_KEY = "progress";
	private static final Type GOAL_LIST_TYPE = new TypeToken<List<Goal>>()
	{
	}.getType();
	private static final Type PROGRESS_TYPE = new TypeToken<Map<String, GoalProgress>>()
	{
	}.getType();

	/**
	 * Another character's goals, for copying to the current one.
	 */
	@Value
	static class CharacterGoals
	{
		String name;
		List<Goal> goals;
	}

	private final ConfigManager configManager;
	private final Gson gson;

	/** Last progress JSON read or written, so unchanged progress isn't written every tick. */
	@Nullable
	private String savedProgress;

	@Inject
	GoalStore(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	List<Goal> loadGoals(String profile)
	{
		return parseGoals(configManager.getConfiguration(DailyGoalsConfig.GROUP, profile, GOALS_KEY));
	}

	void saveGoals(String profile, List<Goal> goals)
	{
		configManager.setConfiguration(DailyGoalsConfig.GROUP, profile, GOALS_KEY, gson.toJson(goals));
	}

	/**
	 * Goals used to be one list shared by every character. Give that list to the first character
	 * that logs in without goals of its own, then remove it.
	 */
	void migrateSharedGoals(String profile)
	{
		String shared = configManager.getConfiguration(DailyGoalsConfig.GROUP, GOALS_KEY);
		if (shared == null)
		{
			return;
		}

		if (configManager.getConfiguration(DailyGoalsConfig.GROUP, profile, GOALS_KEY) == null)
		{
			configManager.setConfiguration(DailyGoalsConfig.GROUP, profile, GOALS_KEY, shared);
		}
		configManager.unsetConfiguration(DailyGoalsConfig.GROUP, GOALS_KEY);
	}

	/**
	 * Every other character that has goals, in RuneLite's profile order.
	 */
	List<CharacterGoals> otherCharacters(String currentProfile)
	{
		List<CharacterGoals> characters = new ArrayList<>();
		for (RuneScapeProfile profile : configManager.getRSProfiles())
		{
			if (profile.getKey().equals(currentProfile))
			{
				continue;
			}

			List<Goal> goals = loadGoals(profile.getKey());
			if (!goals.isEmpty())
			{
				characters.add(new CharacterGoals(characterName(profile), goals));
			}
		}
		return characters;
	}

	/**
	 * The character's name, with the world type for anything but normal worlds, e.g.
	 * "Zezima (Deadman)".
	 */
	String characterName(String profileKey)
	{
		for (RuneScapeProfile profile : configManager.getRSProfiles())
		{
			if (profile.getKey().equals(profileKey))
			{
				return characterName(profile);
			}
		}
		return "This character";
	}

	private static String characterName(RuneScapeProfile profile)
	{
		String name = profile.getDisplayName() == null ? "Unnamed character" : profile.getDisplayName();
		return profile.getType() == RuneScapeProfileType.STANDARD ? name : name + " (" + Text.titleCase(profile.getType()) + ")";
	}

	/**
	 * The account's progress per goal id; empty when there's none yet.
	 */
	Map<String, GoalProgress> loadProgress(String profile)
	{
		String json = configManager.getConfiguration(DailyGoalsConfig.GROUP, profile, PROGRESS_KEY);
		savedProgress = json;
		if (json == null)
		{
			return new HashMap<>();
		}

		try
		{
			Map<String, GoalProgress> progress = gson.fromJson(json, PROGRESS_TYPE);
			if (progress != null)
			{
				progress.values().removeIf(p -> p == null || p.target == null);
				progress.values().forEach(p ->
				{
					if (p.history == null)
					{
						p.history = new ArrayList<>();
					}
				});
				return progress;
			}
		}
		catch (JsonParseException e)
		{
			log.warn("Couldn't read saved progress: {}", json, e);
		}
		return new HashMap<>();
	}

	/**
	 * Write the account's progress, if it changed since the last read or write.
	 */
	void saveProgress(String profile, Map<String, GoalProgress> progress)
	{
		String json = gson.toJson(progress);
		if (!json.equals(savedProgress))
		{
			configManager.setConfiguration(DailyGoalsConfig.GROUP, profile, PROGRESS_KEY, json);
			savedProgress = json;
		}
	}

	/**
	 * Forget the last saved progress, e.g. when another account logs in.
	 */
	void clearProgressCache()
	{
		savedProgress = null;
	}

	private List<Goal> parseGoals(@Nullable String json)
	{
		List<Goal> saved = null;
		try
		{
			saved = json == null ? null : gson.fromJson(json, GOAL_LIST_TYPE);
		}
		catch (JsonParseException e)
		{
			log.warn("Couldn't read saved goals: {}", json, e);
		}

		List<Goal> goals = new ArrayList<>();
		if (saved != null)
		{
			for (Goal goal : saved)
			{
				if (goal != null)
				{
					goals.add(fillDefaults(goal));
				}
			}
		}
		return goals;
	}

	/**
	 * Fill in anything an older or hand-edited save left out.
	 */
	private static Goal fillDefaults(Goal goal)
	{
		if (goal.getId() == null)
		{
			goal.setId(UUID.randomUUID().toString());
		}
		if (goal.getType() == null)
		{
			goal.setType(Goal.Type.XP);
		}
		if (goal.getSkill() == null)
		{
			goal.setSkill(Skill.ATTACK);
		}
		if (goal.getActivity() == null)
		{
			goal.setActivity(Activity.OTHER);
		}
		if (goal.getPeriod() == null)
		{
			goal.setPeriod(Goal.Period.DAILY);
		}
		if ((goal.getDays() & Goal.ALL_DAYS) == 0)
		{
			goal.setDays(Goal.ALL_DAYS);
		}
		goal.setAmount(Math.max(1, goal.getAmount()));
		return goal;
	}
}

package com.dailygoals;

import java.awt.Color;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import lombok.Builder;
import lombok.Value;

/**
 * An immutable snapshot of one goal for the sidebar. It's built on the client thread and handed
 * to the Swing thread, so the panel never touches live {@link GoalProgress}.
 */
@Value
@Builder
class GoalView
{
	static final int HISTORY_BARS = 30;

	Goal goal;
	BufferedImage icon;
	/** Bar colour, amber when behind pace. */
	Color color;
	/** False while logged out; the numbers below are then all zero. */
	boolean tracking;
	/** False on a day the goal doesn't count. */
	boolean active;
	long done;
	long target;
	long left;
	long over;
	long extra;
	long missed;
	boolean complete;
	long rate;
	/** -1 when unknown. */
	long etaMillis;
	long pace;
	/** Where an even pace is on the bar, 0-1000. */
	int pacePermille;
	int streak;
	int bestStreak;
	int weekendPercent;
	/** Oldest first, ending with the current period. */
	List<HistoryBar> history;

	/**
	 * A goal with no progress to show (logged out).
	 */
	static GoalView loggedOut(Goal goal, BufferedImage icon, Color color)
	{
		long amount = goal.isLevel() ? 0 : goal.getAmount();
		return GoalView.builder()
			.goal(goal.copy())
			.icon(icon)
			.color(color)
			.active(true)
			.target(amount)
			.left(amount)
			.etaMillis(-1)
			.history(Collections.emptyList())
			.build();
	}

	static GoalView of(GoalStatus status, BufferedImage icon, Color color, GoalSchedule schedule)
	{
		GoalProgress progress = status.getProgress();
		return GoalView.builder()
			.goal(status.getGoal().copy())
			.icon(icon)
			.color(color)
			.tracking(true)
			.active(status.isActive())
			.done(status.getDone())
			.target(status.getTarget())
			.left(status.getLeft())
			.over(status.getOver())
			.extra(progress.extra)
			.missed(progress.missed)
			.complete(status.isComplete())
			.rate(status.getRate())
			.etaMillis(status.getEtaMillis())
			.pace(status.getPace())
			.pacePermille((int) Math.round(status.getPaceFraction() * 1000))
			.streak(status.getStreak())
			.bestStreak(Math.max(progress.bestStreak, status.getStreak()))
			.weekendPercent(status.getWeekendPercent())
			.history(history(status, schedule))
			.build();
	}

	/**
	 * The last {@link #HISTORY_BARS} periods, oldest first, ending with the current one.
	 */
	private static List<HistoryBar> history(GoalStatus status, GoalSchedule schedule)
	{
		Goal goal = status.getGoal();
		GoalProgress progress = status.getProgress();
		Map<Long, GoalProgress.PeriodResult> results = new HashMap<>();
		for (GoalProgress.PeriodResult result : progress.history)
		{
			results.put(result.day, result);
		}

		List<HistoryBar> bars = new ArrayList<>();
		bars.add(new HistoryBar(status.isActive() ? HistoryBar.Kind.CURRENT : HistoryBar.Kind.REST,
			Math.min(1, status.percent() / 100), schedule.label(goal, progress.day) + " (now)"));

		long day = progress.day;
		for (int i = 1; i < HISTORY_BARS; i++)
		{
			day = schedule.previousPeriodStart(goal, day);
			String label = schedule.label(goal, day);
			GoalProgress.PeriodResult result = results.get(day);
			if (result != null)
			{
				bars.add(new HistoryBar(result.isDone() ? HistoryBar.Kind.DONE : HistoryBar.Kind.MISSED,
					result.goal <= 0 ? 1 : Math.min(1, result.done / (double) result.goal),
					label + ": " + Formats.number(result.done) + " / " + Formats.number(result.goal)));
			}
			else if (!schedule.isActive(goal, day))
			{
				bars.add(new HistoryBar(HistoryBar.Kind.REST, 0, label + ": rest day"));
			}
			else
			{
				bars.add(new HistoryBar(HistoryBar.Kind.NONE, 0, label + ": not played"));
			}
		}
		Collections.reverse(bars);
		return bars;
	}

	/**
	 * One period in the history chart.
	 */
	@Value
	static class HistoryBar
	{
		enum Kind
		{
			/** The goal didn't count that day. */
			REST,
			/** Nothing was recorded (not played). */
			NONE,
			DONE,
			MISSED,
			/** The period in progress. */
			CURRENT
		}

		Kind kind;
		/** Progress toward the goal, 0 to 1. */
		double ratio;
		/** Tooltip text. */
		String label;
	}
}

package com.dailygoals;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.event.MouseEvent;
import java.util.Collections;
import java.util.List;
import javax.swing.JComponent;
import net.runelite.client.ui.ColorScheme;

/**
 * A small bar chart of a goal's recent periods: green reached, red missed, the goal's colour for
 * the current period, a grey line for not played and a dot for rest days. Hover for details.
 */
class HistoryChart extends JComponent
{
	private static final int HEIGHT = 22;
	private static final Color MISSED = new Color(150, 60, 60);

	private List<GoalView.HistoryBar> bars = Collections.emptyList();
	private Color currentColor = Color.WHITE;

	HistoryChart()
	{
		setPreferredSize(new Dimension(100, HEIGHT));
		// Turns tooltips on; the text comes from getToolTipText(MouseEvent)
		setToolTipText("");
	}

	void setBars(List<GoalView.HistoryBar> bars, Color currentColor)
	{
		if (!bars.equals(this.bars) || !currentColor.equals(this.currentColor))
		{
			this.bars = bars;
			this.currentColor = currentColor;
			repaint();
		}
	}

	@Override
	public String getToolTipText(MouseEvent event)
	{
		if (bars.isEmpty())
		{
			return null;
		}
		int index = event.getX() * bars.size() / Math.max(1, getWidth());
		return index >= 0 && index < bars.size() ? bars.get(index).getLabel() : null;
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		int count = bars.size();
		if (count == 0)
		{
			return;
		}

		int width = getWidth();
		int height = getHeight();
		g.setColor(ColorScheme.DARK_GRAY_COLOR);
		g.fillRect(0, 0, width, height);

		for (int i = 0; i < count; i++)
		{
			GoalView.HistoryBar bar = bars.get(i);
			int x = i * width / count;
			int w = Math.max(1, (i + 1) * width / count - x - 1);
			switch (bar.getKind())
			{
				case REST:
					g.setColor(ColorScheme.MEDIUM_GRAY_COLOR);
					g.fillRect(x + w / 2, height - 3, 1, 1);
					break;
				case NONE:
					g.setColor(ColorScheme.MEDIUM_GRAY_COLOR);
					g.fillRect(x, height - 2, w, 2);
					break;
				default:
					g.setColor(barColor(bar.getKind()));
					int h = Math.max(2, (int) Math.round(bar.getRatio() * (height - 2)));
					g.fillRect(x, height - h, w, h);
					break;
			}
		}
	}

	private Color barColor(GoalView.HistoryBar.Kind kind)
	{
		switch (kind)
		{
			case DONE:
				return PanelStyle.GOOD;
			case MISSED:
				return MISSED;
			default:
				return currentColor;
		}
	}
}

package com.dailygoals;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Insets;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import javax.swing.ImageIcon;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * Small Swing building blocks shared by the sidebar's parts, so they look alike.
 */
final class PanelStyle
{
	static final Color GOOD = ColorScheme.PROGRESS_COMPLETE_COLOR;

	private PanelStyle()
	{
	}

	static JLabel smallLabel(String text)
	{
		JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		return label;
	}

	static JLabel valueLabel()
	{
		JLabel label = new JLabel();
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(Color.WHITE);
		label.setHorizontalAlignment(SwingConstants.RIGHT);
		return label;
	}

	static JLabel heading(String text, Color color)
	{
		JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeBoldFont());
		label.setForeground(color);
		return label;
	}

	/**
	 * A small label above a control.
	 */
	static JPanel field(String name, JComponent control)
	{
		JPanel field = new JPanel(new BorderLayout(0, 2));
		field.setOpaque(false);
		field.add(smallLabel(name), BorderLayout.NORTH);
		field.add(control, BorderLayout.CENTER);
		return field;
	}

	/**
	 * "Key:" on the left, value on the right.
	 */
	static JPanel statRow(JLabel key, JLabel value)
	{
		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setOpaque(false);
		row.add(key, BorderLayout.WEST);
		row.add(value, BorderLayout.CENTER);
		return row;
	}

	static JButton smallButton(String text)
	{
		JButton button = new JButton(text);
		button.setFont(FontManager.getRunescapeSmallFont());
		button.setFocusPainted(false);
		button.setMargin(new Insets(2, 4, 2, 4));
		return button;
	}

	static JButton iconButton(ImageIcon icon, String tooltip, boolean enabled)
	{
		JButton button = new JButton(icon);
		button.setToolTipText(tooltip);
		button.setEnabled(enabled);
		button.setFocusPainted(false);
		button.setMargin(new Insets(0, 0, 0, 0));
		button.setPreferredSize(new Dimension(22, 18));
		return button;
	}

	/**
	 * A small filled triangle; Swing greys it out when its button is disabled.
	 */
	static ImageIcon arrowIcon(boolean up)
	{
		BufferedImage image = new BufferedImage(9, 5, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(Color.WHITE);
		g.fillPolygon(new int[]{0, 9, 4}, up ? new int[]{5, 5, 0} : new int[]{0, 0, 5}, 3);
		g.dispose();
		return new ImageIcon(image);
	}
}

package com.dailygoals;

/**
 * Per-hour rate for one goal during this login. Like the XP Tracker, XP goals start the clock at
 * the first XP drop. Kill count goals start it when tracking begins, since one kill right after
 * the start would otherwise read as thousands per hour.
 */
class RateTracker
{
	private final boolean startOnFirstGain;
	private boolean started;
	private long startMillis;
	private long startProgress;
	private long lastProgress = -1;

	RateTracker(boolean startOnFirstGain)
	{
		this.startOnFirstGain = startOnFirstGain;
	}

	void observe(long progress, long now)
	{
		if (!started && (!startOnFirstGain ? lastProgress < 0 : lastProgress >= 0 && progress > lastProgress))
		{
			started = true;
			startMillis = now;
			startProgress = startOnFirstGain ? lastProgress : progress;
		}
		lastProgress = progress;
	}

	long perHour(long now)
	{
		long elapsed = now - startMillis;
		if (!started || elapsed <= 0)
		{
			return 0;
		}
		return (lastProgress - startProgress) * 3_600_000L / elapsed;
	}
}

package com.dailygoals;

import java.awt.Component;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import javax.annotation.Nullable;
import javax.swing.DefaultComboBoxModel;
import javax.swing.DefaultListCellRenderer;
import javax.swing.ImageIcon;
import javax.swing.JComboBox;
import javax.swing.JList;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import lombok.Value;
import net.runelite.api.Skill;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.ImageUtil;

/**
 * The goal editor's "Track" list: Overall and every skill, then each kind of activity, under
 * headings that can't be picked. Items are {@link #OVERALL}, {@link Skill}s and {@link Activity}s.
 */
class TargetPicker extends JComboBox<Object>
{
	/** Total XP; {@code Skill.OVERALL} isn't a usable skill. */
	static final String OVERALL = "Overall";
	private static final int ICON_SIZE = 16;

	private final SkillIconManager skillIconManager;
	private final SpriteManager spriteManager;
	private final Map<Activity, ImageIcon> activityIcons = new EnumMap<>(Activity.class);

	TargetPicker(SkillIconManager skillIconManager, SpriteManager spriteManager)
	{
		super(new HeadingModel(choices()));
		this.skillIconManager = skillIconManager;
		this.spriteManager = spriteManager;
		setMaximumRowCount(16);
		setRenderer(new Renderer());
	}

	/**
	 * Select what a goal tracks.
	 */
	void select(Goal goal)
	{
		if (!goal.isXp())
		{
			setSelectedItem(goal.getActivity());
		}
		else
		{
			setSelectedItem(goal.isOverall() && !goal.isLevel() ? OVERALL : goal.getSkill());
		}
	}

	boolean isActivitySelected()
	{
		return getSelectedItem() instanceof Activity;
	}

	/**
	 * The selected skill, or null for Overall or an activity.
	 */
	@Nullable
	Skill selectedSkill()
	{
		return getSelectedItem() instanceof Skill ? (Skill) getSelectedItem() : null;
	}

	@Nullable
	Activity selectedActivity()
	{
		return isActivitySelected() ? (Activity) getSelectedItem() : null;
	}

	private static Object[] choices()
	{
		List<Object> choices = new ArrayList<>();
		choices.add(new Heading("Skills"));
		choices.add(OVERALL);
		Collections.addAll(choices, (Object[]) Skill.values());
		for (Activity.Category category : Activity.Category.values())
		{
			choices.add(new Heading(category.getLabel()));
			for (Activity activity : Activity.values())
			{
				if (activity.getCategory() == category)
				{
					choices.add(activity);
				}
			}
		}
		return choices.toArray();
	}

	@Nullable
	private ImageIcon icon(Object item)
	{
		if (item instanceof Activity)
		{
			return activityIcon((Activity) item);
		}
		if (item instanceof Skill)
		{
			return new ImageIcon(ImageUtil.resizeImage(skillIconManager.getSkillImage((Skill) item, true), ICON_SIZE, ICON_SIZE));
		}
		if (OVERALL.equals(item))
		{
			BufferedImage image = ImageUtil.loadImageResource(TargetPicker.class, "overall_small.png");
			return new ImageIcon(ImageUtil.resizeImage(image, ICON_SIZE, ICON_SIZE));
		}
		return null;
	}

	/**
	 * Activity icons are game sprites, which load in the background.
	 */
	@Nullable
	private ImageIcon activityIcon(Activity activity)
	{
		if (!activityIcons.containsKey(activity))
		{
			activityIcons.put(activity, null);
			spriteManager.getSpriteAsync(activity.getSpriteId(), 0, sprite ->
				SwingUtilities.invokeLater(() ->
				{
					activityIcons.put(activity, new ImageIcon(ImageUtil.resizeImage(sprite, ICON_SIZE, ICON_SIZE)));
					repaint();
				}));
		}
		return activityIcons.get(activity);
	}

	@Value
	private static class Heading
	{
		String text;
	}

	/**
	 * Skips headings: selecting one, or stepping onto one with the arrow keys, moves on to the
	 * nearest item in the direction of travel.
	 */
	private static class HeadingModel extends DefaultComboBoxModel<Object>
	{
		HeadingModel(Object[] items)
		{
			super(items);
		}

		@Override
		public void setSelectedItem(Object item)
		{
			if (!(item instanceof Heading))
			{
				super.setSelectedItem(item);
				return;
			}

			int index = getIndexOf(item);
			int step = index < getIndexOf(getSelectedItem()) ? -1 : 1;
			for (int i = index + step; i >= 0 && i < getSize(); i += step)
			{
				if (!(getElementAt(i) instanceof Heading))
				{
					super.setSelectedItem(getElementAt(i));
					return;
				}
			}
		}
	}

	private class Renderer extends DefaultListCellRenderer
	{
		@Override
		public Component getListCellRendererComponent(JList<?> list, Object value, int index, boolean isSelected, boolean cellHasFocus)
		{
			boolean heading = value instanceof Heading;
			super.getListCellRendererComponent(list, value, index, isSelected && !heading, cellHasFocus);
			setIcon(icon(value));

			if (heading)
			{
				setText(((Heading) value).getText());
				setFont(FontManager.getRunescapeBoldFont());
				setForeground(ColorScheme.BRAND_ORANGE);
				setBorder(new EmptyBorder(6, 4, 2, 4));
				return this;
			}

			if (value instanceof Skill)
			{
				setText(((Skill) value).getName());
			}
			else if (value instanceof Activity)
			{
				setText(((Activity) value).pickerName());
			}
			setFont(list.getFont());
			// Items are indented under their heading in the open list, but not in the closed box
			setBorder(new EmptyBorder(2, index < 0 ? 4 : 12, 2, 4));
			return this;
		}
	}
}

package com.dailygoals;

import java.util.List;
import net.runelite.api.Skill;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class CountMessageTest
{
	@Test
	public void bossKill()
	{
		assertCounts("Your Zulrah kill count is: <col=ff0000>1,234</col>.", Activity.ZULRAH, 1234);
	}

	@Test
	public void apostropheAndCase()
	{
		assertCounts("Your Kree'arra kill count is: <col=ff0000>87</col>.", Activity.KREEARRA, 87);
	}

	@Test
	public void raidCompletions()
	{
		assertCounts("Your completed Chambers of Xeric count is: <col=ff0000>50</col>.", Activity.CHAMBERS_OF_XERIC, 50);
		assertCounts("Your completed Theatre of Blood: Hard Mode count is: <col=ff0000>3</col>.", Activity.THEATRE_OF_BLOOD_HARD_MODE, 3);
		assertCounts("Your completed Tombs of Amascut: Expert Mode count is: <col=ff0000>12</col>.", Activity.TOMBS_OF_AMASCUT_EXPERT, 12);
	}

	@Test
	public void otherWordings()
	{
		assertCounts("Your Barrows chest count is: <col=ff0000>400</col>.", Activity.BARROWS_CHESTS, 400);
		assertCounts("Your Gauntlet completion count is: <col=ff0000>9</col>.", Activity.THE_GAUNTLET, 9);
		assertCounts("Your Corrupted Gauntlet completion count is: <col=ff0000>9</col>.", Activity.THE_CORRUPTED_GAUNTLET, 9);
		assertCounts("Your subdued Wintertodt count is: <col=ff0000>600</col>.", Activity.WINTERTODT, 600);
	}

	@Test
	public void bossesDontMatchEachOther()
	{
		CountMessage gauntlet = only("Your Corrupted Gauntlet completion count is: <col=ff0000>9</col>.");
		assertFalse(goal(Activity.THE_GAUNTLET, "").counts(gauntlet));
		CountMessage phosani = only("Your Phosani's Nightmare kill count is: <col=ff0000>2</col>.");
		assertFalse(goal(Activity.NIGHTMARE, "").counts(phosani));
	}

	@Test
	public void otherBossByName()
	{
		CountMessage hespori = only("Your Hespori kill count is: <col=ff0000>14</col>.");
		assertTrue(goal(Activity.OTHER, "hespori").counts(hespori));
		assertFalse(goal(Activity.OTHER, "").counts(hespori));
	}

	@Test
	public void xpGoalsIgnoreCounts()
	{
		Goal xp = new Goal("id", Goal.Type.XP, Skill.ATTACK, false, Activity.ZULRAH, "", 100, Goal.Period.DAILY, Goal.ALL_DAYS, true, true, true);
		assertFalse(xp.counts(only("Your Zulrah kill count is: <col=ff0000>5</col>.")));
	}

	@Test
	public void clues()
	{
		List<CountMessage> counts = CountMessage.parse("You have completed <col=ff0000>1,204</col> hard Treasure Trails.");
		assertEquals(2, counts.size());

		// The tier's running total...
		assertTrue(goal(Activity.CLUES_HARD, "").counts(counts.get(0)));
		assertFalse(goal(Activity.CLUES_MEDIUM, "").counts(counts.get(0)));
		assertEquals(1204, counts.get(0).getValue());
		assertFalse(counts.get(0).isIncrement());

		// ...and one more for "all tiers"
		assertTrue(goal(Activity.CLUES_ALL, "").counts(counts.get(1)));
		assertEquals(1, counts.get(1).getValue());
		assertTrue(counts.get(1).isIncrement());

		assertEquals(2, CountMessage.parse("You have completed 1 beginner Treasure Trail.").size());
	}

	@Test
	public void riftsAndSepulchre()
	{
		CountMessage rifts = only("Amount of rifts you have closed: <col=ff0000>321</col>.");
		assertTrue(goal(Activity.RIFTS_CLOSED, "").counts(rifts));
		assertEquals(321, rifts.getValue());

		CountMessage floors = only("You have completed Floor 5 of the Hallowed Sepulchre! Total completions: <col=ff0000>88</col>.");
		assertTrue(goal(Activity.SEPULCHRE_FLOORS, "").counts(floors));
		assertEquals(88, floors.getValue());
	}

	@Test
	public void otherMessagesAreIgnored()
	{
		assertTrue(CountMessage.parse("Welcome to Old School RuneScape.").isEmpty());
		// "Your X is: N" without kill/count words isn't a kill count
		assertTrue(CountMessage.parse("Your reward is: <col=ff0000>5</col>.").isEmpty());
	}

	@Test
	public void namesNormalize()
	{
		assertEquals(Activity.normalize("Hallowed Sepulchre"), Activity.normalize("hallowed  sepulchre"));
		assertEquals(Activity.normalize("Kree'Arra"), Activity.normalize("kreearra"));
		assertEquals(Activity.normalize("The Gauntlet"), Activity.normalize("Gauntlet"));
	}

	private static void assertCounts(String message, Activity activity, long value)
	{
		CountMessage count = only(message);
		assertTrue(count.getName(), goal(activity, "").counts(count));
		assertEquals(value, count.getValue());
		assertFalse(count.isIncrement());
	}

	private static CountMessage only(String message)
	{
		List<CountMessage> counts = CountMessage.parse(message);
		assertEquals(message, 1, counts.size());
		return counts.get(0);
	}

	private static Goal goal(Activity activity, String customName)
	{
		return new Goal("id", Goal.Type.COUNT, Skill.ATTACK, false, activity, customName, 10, Goal.Period.DAILY, Goal.ALL_DAYS, true, true, true);
	}
}

