package com.dailygoals;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class FormatsTest
{
	@Test
	public void numbers()
	{
		assertEquals("12,345", Formats.number(12_345));
		assertEquals("10K", Formats.shortNumber(10_000));
	}

	@Test
	public void durations()
	{
		assertEquals("-", Formats.duration(-1));
		assertEquals("<1m", Formats.duration(30_000));
		assertEquals("23m", Formats.duration(23 * 60_000));
		assertEquals("1h 5m", Formats.duration(65 * 60_000));
		assertEquals("5d", Formats.duration(120 * 3_600_000L));
	}

	@Test
	public void percentages()
	{
		assertEquals("45.0%", Formats.percent(45_000, 100_000));
		assertEquals("110.0%", Formats.percent(110, 100));
		// Rounded down, so it never reads 100% before the goal is done
		assertEquals("99%", Formats.shortPercent(99_999, 100_000));
		assertEquals("10%", Formats.shortPercent(10_000, 100_000));
		assertEquals("+12.0%", Formats.pacePercent(12, 100));
		assertEquals("-5.0%", Formats.pacePercent(-5, 100));
	}

	@Test
	public void pace()
	{
		assertEquals("+12,000", Formats.pace(12_000));
		assertEquals("+0", Formats.pace(0));
		assertEquals("-5,000", Formats.pace(-5_000));
	}
}

package com.dailygoals;

import com.dailygoals.DailyGoalsConfig.CarryOver;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class GoalProgressTest
{
	@Test
	public void xpCountsFromFirstSeen()
	{
		GoalProgress state = new GoalProgress("xp:ATTACK", 0);
		state.observeXp(1_000_000);
		state.observeXp(1_040_000);
		assertEquals(40_000, state.progress());
		assertEquals(60_000, state.left(100_000));
		assertFalse(state.isDone(100_000));
	}

	@Test
	public void firstKillMessageCountsAsOneKill()
	{
		GoalProgress state = new GoalProgress("kc:ZULRAH", 0);
		state.observeTotal(500);
		assertEquals(1, state.progress());
		state.observeTotal(503);
		assertEquals(4, state.progress());
	}

	@Test
	public void noCarryOver()
	{
		GoalProgress state = played(150);
		state.rollover(1, 100, CarryOver.OFF, true, false);
		assertEquals(0, state.progress());
		assertEquals(100, state.goal(100));
	}

	@Test
	public void extraProgressCarries()
	{
		GoalProgress state = played(150);
		state.rollover(1, 100, CarryOver.EXTRA, true, false);
		assertEquals(50, state.progress());
		assertEquals(100, state.goal(100));
	}

	@Test
	public void missedAmountCarries()
	{
		GoalProgress state = played(70);
		state.rollover(1, 100, CarryOver.MISSED, true, false);
		assertEquals(0, state.progress());
		assertEquals(130, state.goal(100));

		// Only the extra direction is ignored in MISSED mode
		state = played(150);
		state.rollover(1, 100, CarryOver.MISSED, true, false);
		assertEquals(0, state.progress());
		assertEquals(100, state.goal(100));
	}

	@Test
	public void bothCarriesSettleAgainstEachOther()
	{
		GoalProgress state = played(70);
		state.rollover(1, 100, CarryOver.BOTH, true, false);
		assertEquals(130, state.goal(100));

		// 160 done against 130 needed: 30 extra goes to the next day, the missed amount is cleared
		state.observeXp(1_000 + 70 + 160);
		state.rollover(2, 100, CarryOver.BOTH, true, false);
		assertEquals(30, state.progress());
		assertEquals(100, state.goal(100));
	}

	@Test
	public void rolloverKeepsCountingFromLastSeenValue()
	{
		GoalProgress state = played(150);
		state.completed = true;
		state.rollover(1, 100, CarryOver.OFF, true, false);
		assertFalse(state.completed);
		assertEquals(1, state.day);

		// XP gained while the client was closed counts toward the new day
		state.observeXp(1_000 + 150 + 25);
		assertEquals(25, state.progress());
	}

	@Test
	public void rolloverBeforeAnythingSeen()
	{
		GoalProgress state = new GoalProgress("kc:ZULRAH", 0);
		state.rollover(1, 5, CarryOver.BOTH, true, false);
		assertNull(state.baseline);
		assertEquals(10, state.goal(5));
		state.observeTotal(42);
		assertEquals(1, state.progress());
		assertTrue(state.left(5) == 9);
	}

	@Test
	public void streakAndHistory()
	{
		GoalProgress state = played(150);
		state.rollover(1, 100, CarryOver.OFF, true, false);
		assertEquals(1, state.streak);
		assertEquals(1, state.history.size());
		assertEquals(150, state.history.get(0).done);
		assertEquals(100, state.history.get(0).goal);

		// Done again: streak grows, and counts today once today is done
		state.observeXp(1_000 + 150 + 100);
		assertEquals(2, state.currentStreak(100, true));
		state.rollover(2, 100, CarryOver.OFF, true, false);
		assertEquals(2, state.streak);

		// A missed day ends it, but the best is kept
		state.observeXp(1_000 + 250 + 10);
		state.rollover(3, 100, CarryOver.OFF, true, false);
		assertEquals(0, state.streak);
		assertEquals(2, state.bestStreak);
	}

	@Test
	public void restDaysKeepStreakAndCarry()
	{
		GoalProgress state = played(70);
		state.rollover(1, 100, CarryOver.MISSED, true, false);
		assertEquals(30, state.missed);
		// A rest day passes the carry-over on and leaves the streak alone
		state.rollover(2, 100, CarryOver.MISSED, false, false);
		assertEquals(30, state.missed);
		assertEquals(1, state.history.size());
	}

	@Test
	public void skippedDayEndsStreak()
	{
		GoalProgress state = played(150);
		state.rollover(5, 100, CarryOver.OFF, true, true);
		assertEquals(0, state.streak);
		assertEquals(1, state.bestStreak);
	}

	@Test
	public void milestoneResetsEachPeriod()
	{
		GoalProgress state = played(80);
		state.milestone = 75;
		state.rollover(1, 100, CarryOver.OFF, true, false);
		assertEquals(0, state.milestone);
	}

	@Test
	public void overAndCountIncrements()
	{
		GoalProgress state = played(150);
		assertEquals(50, state.over(100));
		assertEquals(0, state.left(100));

		GoalProgress clues = new GoalProgress("kc:CLUES_ALL", 0);
		clues.add(1);
		clues.add(1);
		assertEquals(2, clues.progress());
	}

	@Test
	public void olderSavesGetAnEmptyHistory()
	{
		GoalProgress state = new com.google.gson.Gson().fromJson("{\"target\":\"xp:ATTACK\",\"day\":5,\"gained\":3}", GoalProgress.class);
		assertEquals(0, state.history.size());
		assertEquals(3, state.progress());
	}

	private static GoalProgress played(long xp)
	{
		GoalProgress state = new GoalProgress("xp:ATTACK", 0);
		state.observeXp(1_000);
		state.observeXp(1_000 + xp);
		return state;
	}
}

package com.dailygoals;

import java.time.DayOfWeek;
import java.time.LocalTime;
import java.time.ZoneOffset;
import java.time.ZonedDateTime;
import net.runelite.api.Skill;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class GoalScheduleTest
{
	private static final GoalSchedule SCHEDULE = new GoalSchedule(ZoneOffset.UTC, LocalTime.of(4, 0), DayOfWeek.WEDNESDAY);

	@Test
	public void dailyPeriods()
	{
		Goal goal = goal(Goal.Period.DAILY, Goal.ALL_DAYS);
		// Thursday 2026-10-22 14:00 is in the period that started at 04:00 that day
		long start = SCHEDULE.periodStart(goal, utc(2026, 10, 22, 14));
		assertEquals(utc(2026, 10, 22, 4), start);
		assertEquals(utc(2026, 10, 23, 4), SCHEDULE.nextPeriodStart(goal, start));
		assertEquals(utc(2026, 10, 21, 4), SCHEDULE.previousPeriodStart(goal, start));
		// 10 hours into a 24 hour day
		assertEquals(10 / 24.0, SCHEDULE.elapsedFraction(goal, start, utc(2026, 10, 22, 14)), 1e-9);
	}

	@Test
	public void weeklyPeriods()
	{
		Goal goal = goal(Goal.Period.WEEKLY, Goal.ALL_DAYS);
		// Thursday belongs to the week that started Wednesday 04:00
		long start = SCHEDULE.periodStart(goal, utc(2026, 10, 22, 14));
		assertEquals(utc(2026, 10, 21, 4), start);
		assertEquals(utc(2026, 10, 28, 4), SCHEDULE.nextPeriodStart(goal, start));
		// Wednesday before 04:00 is still the previous week
		assertEquals(utc(2026, 10, 14, 4), SCHEDULE.periodStart(goal, utc(2026, 10, 21, 3)));
	}

	@Test
	public void weekdaysOnly()
	{
		Goal goal = goal(Goal.Period.DAILY, 0b001_1111);
		assertTrue(SCHEDULE.isActive(goal, utc(2026, 10, 23, 4)));   // Friday
		assertFalse(SCHEDULE.isActive(goal, utc(2026, 10, 24, 4)));  // Saturday
		assertFalse(SCHEDULE.isActive(goal, utc(2026, 10, 25, 4)));  // Sunday

		// Friday to Monday skips only rest days
		assertFalse(SCHEDULE.missedBetween(goal, utc(2026, 10, 23, 4), utc(2026, 10, 26, 4)));
		// Friday to Tuesday skips Monday
		assertTrue(SCHEDULE.missedBetween(goal, utc(2026, 10, 23, 4), utc(2026, 10, 27, 4)));
	}

	@Test
	public void weekend()
	{
		assertFalse(SCHEDULE.isWeekend(utc(2026, 10, 23, 4)));  // Friday
		assertTrue(SCHEDULE.isWeekend(utc(2026, 10, 24, 4)));   // Saturday
		assertTrue(SCHEDULE.isWeekend(utc(2026, 10, 25, 4)));   // Sunday
		// Monday 02:00 is still Sunday's period with a 04:00 reset
		Goal goal = goal(Goal.Period.DAILY, Goal.ALL_DAYS);
		assertTrue(SCHEDULE.isWeekend(SCHEDULE.periodStart(goal, utc(2026, 10, 26, 2))));
	}

	@Test
	public void labels()
	{
		assertEquals("Thu 22 Oct", SCHEDULE.label(goal(Goal.Period.DAILY, Goal.ALL_DAYS), utc(2026, 10, 22, 4)));
		assertEquals("Week of 21 Oct", SCHEDULE.label(goal(Goal.Period.WEEKLY, Goal.ALL_DAYS), utc(2026, 10, 21, 4)));
	}

	private static Goal goal(Goal.Period period, int days)
	{
		return new Goal("id", Goal.Type.XP, Skill.ATTACK, false, Activity.ZULRAH, "", 100, period, days, true, true, true);
	}

	private static long utc(int year, int month, int day, int hour)
	{
		return ZonedDateTime.of(year, month, day, hour, 0, 0, 0, ZoneOffset.UTC).toInstant().toEpochMilli();
	}
}

package com.dailygoals;

import java.time.DayOfWeek;
import java.time.LocalTime;
import java.time.ZoneOffset;
import java.time.ZonedDateTime;
import net.runelite.api.Skill;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class GoalStatusTest
{
	private static final GoalSchedule SCHEDULE = new GoalSchedule(ZoneOffset.UTC, LocalTime.of(4, 0), DayOfWeek.MONDAY);
	private static final long FRIDAY = utc(2026, 10, 23, 4);
	private static final long SATURDAY = utc(2026, 10, 24, 4);

	@Test
	public void weekendMultiplier()
	{
		Goal goal = goal(Goal.Type.XP, 100_000);
		assertEquals(100_000, status(goal, new GoalProgress("xp:ATTACK", FRIDAY), 150).getAmount());

		GoalStatus weekend = status(goal, new GoalProgress("xp:ATTACK", SATURDAY), 150);
		assertEquals(150_000, weekend.getAmount());
		assertEquals(150, weekend.getWeekendPercent());

		// 100% is off
		assertEquals(0, status(goal, new GoalProgress("xp:ATTACK", SATURDAY), 100).getWeekendPercent());

		// Weekly goals aren't scaled
		goal.setPeriod(Goal.Period.WEEKLY);
		assertEquals(100_000, status(goal, new GoalProgress("xp:ATTACK", SATURDAY), 150).getAmount());
	}

	@Test
	public void levelGoalNeedsXpFromPeriodStart()
	{
		Goal goal = goal(Goal.Type.LEVEL, 2);
		GoalProgress progress = new GoalProgress("level:ATTACK:2", SATURDAY);
		// Not seen yet: not reached
		assertEquals(1, status(goal, progress, 200).getAmount());

		progress.observeXp(50);
		// Level 2 is at 83 XP; the weekend multiplier doesn't apply to levels
		GoalStatus status = status(goal, progress, 200);
		assertEquals(33, status.getAmount());
		assertFalse(status.isComplete());

		progress.observeXp(90);
		assertTrue(status(goal, progress, 200).isComplete());
	}

	@Test
	public void percentAndPace()
	{
		Goal goal = goal(Goal.Type.XP, 1_000);
		GoalProgress progress = new GoalProgress("xp:ATTACK", FRIDAY);
		progress.observeXp(0);
		progress.observeXp(1_100);

		// Half way through the day
		GoalStatus status = GoalStatus.of(goal, progress, SCHEDULE, 100, 0, FRIDAY + 12 * 3_600_000L);
		assertEquals(110.0, status.percent(), 1e-9);
		assertEquals(100, status.getOver());
		assertEquals(600, status.getPace());
		assertFalse(status.isBehind());
	}

	private static GoalStatus status(Goal goal, GoalProgress progress, int weekendMultiplier)
	{
		return GoalStatus.of(goal, progress, SCHEDULE, weekendMultiplier, 0, progress.day);
	}

	private static Goal goal(Goal.Type type, int amount)
	{
		return new Goal("id", type, Skill.ATTACK, false, Activity.ZULRAH, "", amount, Goal.Period.DAILY, Goal.ALL_DAYS, true, true, true);
	}

	private static long utc(int year, int month, int day, int hour)
	{
		return ZonedDateTime.of(year, month, day, hour, 0, 0, 0, ZoneOffset.UTC).toInstant().toEpochMilli();
	}
}

package com.dailygoals;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.time.DayOfWeek;
import java.util.Arrays;
import java.util.List;
import net.runelite.api.Skill;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class GoalTest
{
	@Test
	public void targetKeys()
	{
		assertEquals("xp:MINING", xp(Skill.MINING).targetKey());
		assertEquals("kc:VORKATH", count(Activity.VORKATH, "").targetKey());
		assertEquals("kc:other:hallowedsepulchre", count(Activity.OTHER, "Hallowed Sepulchre").targetKey());
		assertNull(count(Activity.OTHER, "  ").targetKey());
	}

	@Test
	public void overall()
	{
		Goal goal = xp(Skill.MINING);
		goal.setOverall(true);
		assertEquals("xp:OVERALL", goal.targetKey());
		assertEquals("Overall XP", goal.name());
	}

	@Test
	public void levelGoal()
	{
		Goal goal = xp(Skill.MINING);
		goal.setType(Goal.Type.LEVEL);
		goal.setAmount(2);
		assertEquals("Level 2 Mining", goal.name());
		assertEquals("level:MINING:2", goal.targetKey());
		// Level 2 is at 83 XP
		assertEquals(83, goal.xpToLevel(0));
		assertEquals(0, goal.xpToLevel(500));
		assertTrue(goal.isXp());
	}

	@Test
	public void weeklyAndDays()
	{
		Goal goal = xp(Skill.MINING);
		goal.setDays(0b001_1111);
		assertTrue(goal.isActiveOn(DayOfWeek.MONDAY));
		assertTrue(goal.isActiveOn(DayOfWeek.FRIDAY));
		assertFalse(goal.isActiveOn(DayOfWeek.SATURDAY));
		goal.setPeriod(Goal.Period.WEEKLY);
		assertEquals("xp:MINING:weekly", goal.targetKey());
	}

	@Test
	public void names()
	{
		assertEquals("Mining XP", xp(Skill.MINING).name());
		assertEquals("Vorkath kills", count(Activity.VORKATH, "").name());
		assertEquals("Hespori kills", count(Activity.OTHER, " Hespori ").name());
		assertEquals("Medium clues", count(Activity.CLUES_MEDIUM, "").name());
		assertEquals("Rifts closed", count(Activity.RIFTS_CLOSED, "").name());
	}

	@Test
	public void rateLabels()
	{
		assertEquals("XP/h", xp(Skill.MINING).rateLabel());
		assertEquals("Kills/h", count(Activity.VORKATH, "").rateLabel());
		assertEquals("Per hour", count(Activity.RIFTS_CLOSED, "").rateLabel());
	}

	@Test
	public void categories()
	{
		assertEquals(Activity.Category.BOSS, Activity.VORKATH.getCategory());
		assertEquals(Activity.Category.RAID, Activity.TOMBS_OF_AMASCUT.getCategory());
		assertEquals(Activity.Category.MINIGAME, Activity.TEMPOROSS.getCategory());
		assertEquals(Activity.Category.CLUE, Activity.CLUES_ALL.getCategory());
		assertEquals(Activity.Category.OTHER, Activity.OTHER.getCategory());
		assertEquals("medium", Activity.CLUES_MEDIUM.clueTier());
	}

	@Test
	public void parseAmount()
	{
		assertEquals(Integer.valueOf(250_000), Goal.parseAmount("250,000"));
		assertEquals(Integer.valueOf(150_000), Goal.parseAmount("150k"));
		assertEquals(Integer.valueOf(150_000), Goal.parseAmount("150K"));
		assertEquals(Integer.valueOf(1_500_000), Goal.parseAmount("1.5m"));
		assertEquals(Integer.valueOf(25), Goal.parseAmount(" 25 "));
		assertNull(Goal.parseAmount("0"));
		assertNull(Goal.parseAmount("lots"));
		assertNull(Goal.parseAmount(""));
		assertNull(Goal.parseAmount("5b"));
	}

	@Test
	public void jsonRoundTrip()
	{
		Gson gson = new Gson();
		List<Goal> goals = Arrays.asList(xp(Skill.SAILING), count(Activity.OTHER, "Hespori"));
		List<Goal> back = gson.fromJson(gson.toJson(goals), new TypeToken<List<Goal>>()
		{
		}.getType());
		assertEquals(goals, back);
	}

	@Test
	public void readsOlderSaves()
	{
		// Before the cleanup: "KC" type, "boss" and "customBoss" fields, no enabled/period/days
		Goal goal = new Gson().fromJson("{\"id\":\"a\",\"type\":\"KC\",\"boss\":\"OTHER\",\"customBoss\":\"Hespori\",\"amount\":5}", Goal.class);
		assertEquals(Goal.Type.COUNT, goal.getType());
		assertEquals(Activity.OTHER, goal.getActivity());
		assertEquals("Hespori", goal.getCustomName());
		assertTrue(goal.isEnabled());
		assertEquals(Goal.Period.DAILY, goal.getPeriod());
		assertEquals(Goal.ALL_DAYS, goal.getDays());
	}

	private static Goal xp(Skill skill)
	{
		return new Goal("id", Goal.Type.XP, skill, false, Activity.ZULRAH, "", 100, Goal.Period.DAILY, Goal.ALL_DAYS, true, true, true);
	}

	private static Goal count(Activity activity, String customName)
	{
		return new Goal("id", Goal.Type.COUNT, Skill.ATTACK, false, activity, customName, 100, Goal.Period.DAILY, Goal.ALL_DAYS, true, true, true);
	}
}

package com.dailygoals;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class RateTrackerTest
{
	private static final long MINUTE = 60_000;

	@Test
	public void xpStartsAtFirstGain()
	{
		RateTracker rate = new RateTracker(true);
		rate.observe(0, 0);
		// Idle time before the first drop doesn't count
		rate.observe(0, 10 * MINUTE);
		assertEquals(0, rate.perHour(10 * MINUTE));

		rate.observe(100, 10 * MINUTE);
		rate.observe(1_000, 40 * MINUTE);
		// 1,000 XP over 30 minutes
		assertEquals(2_000, rate.perHour(40 * MINUTE));
	}

	@Test
	public void killsStartWhenTrackingBegins()
	{
		RateTracker rate = new RateTracker(false);
		rate.observe(3, 0);
		rate.observe(4, MINUTE);
		// One kill a minute in is 60/h, not "one kill in no time"
		assertEquals(60, rate.perHour(MINUTE));
		rate.observe(6, 30 * MINUTE);
		assertEquals(6, rate.perHour(30 * MINUTE));
	}

	@Test
	public void nothingBeforeStart()
	{
		assertEquals(0, new RateTracker(true).perHour(MINUTE));
	}
}

package com.dailygoals;

import java.time.LocalTime;
import java.time.ZoneId;
import java.time.ZoneOffset;
import java.time.ZonedDateTime;
import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class ResetTimeTest
{
	private static final ZoneId STOCKHOLM = ZoneId.of("Europe/Stockholm");

	@Test
	public void afterResetTimeIsToday()
	{
		ZonedDateTime now = ZonedDateTime.of(2026, 10, 22, 14, 0, 0, 0, ZoneOffset.UTC);
		assertEquals(utc(2026, 10, 22, 6, 0), GoalSchedule.lastDailyReset(now, LocalTime.of(6, 0)));
	}

	@Test
	public void beforeResetTimeIsYesterday()
	{
		ZonedDateTime now = ZonedDateTime.of(2026, 10, 22, 5, 59, 0, 0, ZoneOffset.UTC);
		assertEquals(utc(2026, 10, 21, 6, 0), GoalSchedule.lastDailyReset(now, LocalTime.of(6, 0)));
	}

	@Test
	public void exactlyAtResetTimeIsToday()
	{
		ZonedDateTime now = ZonedDateTime.of(2026, 10, 22, 0, 0, 0, 0, ZoneOffset.UTC);
		assertEquals(utc(2026, 10, 22, 0, 0), GoalSchedule.lastDailyReset(now, LocalTime.MIDNIGHT));
	}

	@Test
	public void localTimeZone()
	{
		// 01:30 in Stockholm (UTC+2 in October before the switch) is after a 01:00 local reset
		ZonedDateTime now = ZonedDateTime.of(2026, 10, 22, 1, 30, 0, 0, STOCKHOLM);
		assertEquals(utc(2026, 10, 21, 23, 0), GoalSchedule.lastDailyReset(now, LocalTime.of(1, 0)));
	}

	@Test
	public void dstGapMovesForward()
	{
		// 02:30 doesn't exist in Stockholm on 2026-03-29; the reset falls at 03:30 local = 01:30 UTC
		ZonedDateTime now = ZonedDateTime.of(2026, 3, 29, 12, 0, 0, 0, STOCKHOLM);
		assertEquals(utc(2026, 3, 29, 1, 30), GoalSchedule.lastDailyReset(now, LocalTime.of(2, 30)));
	}

	@Test
	public void parseTime()
	{
		assertEquals(LocalTime.of(6, 30), GoalSchedule.parseTime("06:30"));
		assertEquals(LocalTime.of(6, 30), GoalSchedule.parseTime(" 6.30 "));
		assertEquals(LocalTime.of(6, 30), GoalSchedule.parseTime("0630"));
		assertEquals(LocalTime.of(18, 0), GoalSchedule.parseTime("18"));
		assertEquals(LocalTime.of(23, 59), GoalSchedule.parseTime("23:59"));
		assertEquals(LocalTime.MIDNIGHT, GoalSchedule.parseTime("24:00"));
		assertEquals(LocalTime.MIDNIGHT, GoalSchedule.parseTime("noon"));
		assertEquals(LocalTime.MIDNIGHT, GoalSchedule.parseTime(""));
	}

	private static long utc(int year, int month, int day, int hour, int minute)
	{
		return ZonedDateTime.of(year, month, day, hour, minute, 0, 0, ZoneOffset.UTC).toInstant().toEpochMilli();
	}
}
